module hbci_event_core #(
    parameter integer NUM_CH   = 8,   // number of input channels
    parameter integer CH_W     = 3,   // channel index width
    parameter integer SAMPLE_W = 16,  // signed sample width
    parameter integer FRAC_W   = 8,   // baseline fractional bits
    parameter integer TS_W     = 32,  // timestamp width
    parameter integer REFR_W   = 8    // refractory counter width
) (
    input  wire                       clk,
    input  wire                       rst_n,

    // Configuration (quasi-static; sampled every accepted sample)
    input  wire [SAMPLE_W-1:0]        cfg_threshold,    // |residual| >= threshold fires; 0 disables detection
    input  wire [SAMPLE_W-1:0]        cfg_hysteresis,   // re-arm when |residual| < threshold - hysteresis
    input  wire [REFR_W-1:0]          cfg_refractory,   // samples of the same channel ignored after an event
    input  wire [3:0]                 cfg_alpha_shift,  // baseline EMA: b += (x - b) >>> alpha_shift

    // Sample input stream (valid/ready)
    input  wire                       in_valid,
    output wire                       in_ready,
    input  wire [CH_W-1:0]            in_channel,
    input  wire signed [SAMPLE_W-1:0] in_sample,

    // Event output stream (valid/ready)
    output wire                       ev_valid,
    input  wire                       ev_ready,
    output wire [CH_W-1:0]            ev_channel,
    output wire [TS_W-1:0]            ev_timestamp,
    output wire                       ev_polarity,      // 1 = negative-going residual
    output wire [SAMPLE_W-1:0]        ev_magnitude,     // |residual| at the crossing sample

    // Status counters
    output wire [TS_W-1:0]            stat_samples,     // accepted samples (== next timestamp)
    output wire [TS_W-1:0]            stat_events,      // events emitted
    output wire [TS_W-1:0]            stat_rejected     // handshakes with an out-of-range channel
);
    localparam integer BASE_W = SAMPLE_W + FRAC_W;

    // ---------------------------------------------------------------- handshake
    // Channel index zero-extended to 32 bits so the range check is width-clean.
    wire [31:0] in_channel_x = {{(32-CH_W){1'b0}}, in_channel};
    wire hs        = in_valid & in_ready;
    wire ch_ok     = (in_channel_x < NUM_CH);
    wire accept    = hs & ch_ok;          // a sample that updates channel state
    wire reject    = hs & ~ch_ok;         // consumed but ignored

    // ------------------------------------------------------------ channel state
    wire signed [BASE_W-1:0] st_baseline;
    wire [REFR_W-1:0]        st_refr;
    wire                     st_armed;
    wire                     st_primed;

    wire signed [BASE_W-1:0] nx_baseline;
    wire [REFR_W-1:0]        nx_refr;
    wire                     nx_armed;

    hbci_channel_state #(
        .NUM_CH(NUM_CH), .CH_W(CH_W), .BASE_W(BASE_W), .REFR_W(REFR_W)
    ) u_state (
        .clk(clk), .rst_n(rst_n),
        .ch(in_channel),
        .rd_baseline(st_baseline), .rd_refr(st_refr),
        .rd_armed(st_armed), .rd_primed(st_primed),
        .we(accept),
        .wr_baseline(nx_baseline), .wr_refr(nx_refr), .wr_armed(nx_armed)
    );

    // --------------------------------------------------- baseline and residual
    wire signed [SAMPLE_W:0] residual;

    hbci_baseline_ema #(
        .SAMPLE_W(SAMPLE_W), .FRAC_W(FRAC_W)
    ) u_baseline (
        .sample(in_sample), .baseline_q(st_baseline),
        .alpha_shift(cfg_alpha_shift), .primed(st_primed),
        .residual(residual), .baseline_next(nx_baseline)
    );

    // ------------------------------------------------------- threshold detector
    wire [SAMPLE_W-1:0] magnitude;
    wire                polarity, above, below_rearm, det_enable;

    hbci_threshold_detector #(
        .SAMPLE_W(SAMPLE_W)
    ) u_threshold (
        .residual(residual),
        .threshold(cfg_threshold), .hysteresis(cfg_hysteresis),
        .magnitude(magnitude), .polarity(polarity),
        .above(above), .below_rearm(below_rearm), .enable(det_enable)
    );

    // ----------------------------------------------- hysteresis and refractory
    wire fire;

    hbci_refractory_ctrl #(
        .REFR_W(REFR_W)
    ) u_refractory (
        .primed(st_primed), .enable(det_enable),
        .armed(st_armed), .refr_cnt(st_refr),
        .above(above), .below_rearm(below_rearm),
        .cfg_refractory(cfg_refractory),
        .fire(fire), .armed_next(nx_armed), .refr_next(nx_refr)
    );

    // ---------------------------------------------------------------- timestamp
    wire [TS_W-1:0] ts_now;

    hbci_timestamp #(
        .TS_W(TS_W)
    ) u_timestamp (
        .clk(clk), .rst_n(rst_n),
        .tick(accept), .reject(reject),
        .ts_now(ts_now), .rejected(stat_rejected)
    );
    assign stat_samples = ts_now;

    // ------------------------------------------------------------- event output
    wire ev_push = accept & fire;         // an accepted sample crossed the threshold

    hbci_event_packer #(
        .CH_W(CH_W), .SAMPLE_W(SAMPLE_W), .TS_W(TS_W)
    ) u_packer (
        .clk(clk), .rst_n(rst_n),
        .push(ev_push),
        .in_channel(in_channel), .in_timestamp(ts_now),
        .in_polarity(polarity), .in_magnitude(magnitude),
        .ev_valid(ev_valid), .ev_ready(ev_ready),
        .ev_channel(ev_channel), .ev_timestamp(ev_timestamp),
        .ev_polarity(ev_polarity), .ev_magnitude(ev_magnitude),
        .events(stat_events), .slot_free(in_ready)
    );
endmodule

module hbci_channel_state #(
    parameter integer NUM_CH = 8,
    parameter integer CH_W   = 3,
    parameter integer BASE_W = 24,
    parameter integer REFR_W = 8
) (
    input  wire                     clk,
    input  wire                     rst_n,
    input  wire [CH_W-1:0]          ch,
    output wire signed [BASE_W-1:0] rd_baseline,
    output wire [REFR_W-1:0]        rd_refr,
    output wire                     rd_armed,
    output wire                     rd_primed,
    input  wire                     we,
    input  wire signed [BASE_W-1:0] wr_baseline,
    input  wire [REFR_W-1:0]        wr_refr,
    input  wire                     wr_armed
);
    reg signed [BASE_W-1:0] baseline [0:NUM_CH-1];
    reg [REFR_W-1:0]        refr     [0:NUM_CH-1];
    reg [NUM_CH-1:0]        armed;
    reg [NUM_CH-1:0]        primed;

    // Out-of-range reads return a neutral state; writes are gated by `we`,
    // which the top level only asserts for in-range channels.
    wire [31:0] ch_x = {{(32-CH_W){1'b0}}, ch};
    wire in_range = (ch_x < NUM_CH);
    assign rd_baseline = in_range ? baseline[ch] : {BASE_W{1'b0}};
    assign rd_refr     = in_range ? refr[ch]     : {REFR_W{1'b0}};
    assign rd_armed    = in_range ? armed[ch]    : 1'b1;
    assign rd_primed   = in_range ? primed[ch]   : 1'b0;

    integer i;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < NUM_CH; i = i + 1) begin
                baseline[i] <= {BASE_W{1'b0}};
                refr[i]     <= {REFR_W{1'b0}};
            end
            armed  <= {NUM_CH{1'b1}};
            primed <= {NUM_CH{1'b0}};
        end else if (we) begin
            baseline[ch] <= wr_baseline;
            refr[ch]     <= wr_refr;
            armed[ch]    <= wr_armed;
            primed[ch]   <= 1'b1;
        end
    end
endmodule

module hbci_baseline_ema #(
    parameter integer SAMPLE_W = 16,
    parameter integer FRAC_W   = 8
) (
    input  wire signed [SAMPLE_W-1:0]        sample,
    input  wire signed [SAMPLE_W+FRAC_W-1:0] baseline_q,
    input  wire [3:0]                        alpha_shift,
    input  wire                              primed,
    output wire signed [SAMPLE_W:0]          residual,
    output wire signed [SAMPLE_W+FRAC_W-1:0] baseline_next
);
    localparam integer BASE_W = SAMPLE_W + FRAC_W;

    // Integer part of the baseline: the top SAMPLE_W bits of the two's-complement
    // Q value, i.e. baseline_q >>> FRAC_W (arithmetic shift = floor).
    wire signed [SAMPLE_W-1:0] base_int = baseline_q[BASE_W-1:FRAC_W];

    // One extra bit so that e.g. -32768 - 32767 = -65535 cannot overflow.
    wire signed [SAMPLE_W:0] sample_x = {sample[SAMPLE_W-1], sample};       // sign-extended
    wire signed [SAMPLE_W:0] base_x   = {base_int[SAMPLE_W-1], base_int};   // sign-extended
    wire signed [SAMPLE_W:0] diff     = sample_x - base_x;
    assign residual = primed ? diff : {(SAMPLE_W+1){1'b0}};

    // EMA update in Q(SAMPLE_W).FRAC_W with one guard bit.
    wire signed [BASE_W:0] sample_q = {sample[SAMPLE_W-1], sample, {FRAC_W{1'b0}}};
    wire signed [BASE_W:0] base_q_x = {baseline_q[BASE_W-1], baseline_q};
    wire signed [BASE_W:0] err_q    = sample_q - base_q_x;
    wire signed [BASE_W:0] step_q   = err_q >>> alpha_shift;
    // Guard bit sum_q[BASE_W] is never read: it always equals sum_q[BASE_W-1]
    // (checked at every accepted sample by tb/tb_hbci_stream.v).
    /* verilator lint_off UNUSEDSIGNAL */
    wire signed [BASE_W:0] sum_q    = base_q_x + step_q;
    /* verilator lint_on UNUSEDSIGNAL */
    // The EMA result always lies between baseline and sample, so it fits BASE_W.
    assign baseline_next = primed ? sum_q[BASE_W-1:0] : sample_q[BASE_W-1:0];
endmodule

module hbci_threshold_detector #(
    parameter integer SAMPLE_W = 16
) (
    input  wire signed [SAMPLE_W:0] residual,
    input  wire [SAMPLE_W-1:0]      threshold,
    input  wire [SAMPLE_W-1:0]      hysteresis,
    output wire [SAMPLE_W-1:0]      magnitude,
    output wire                     polarity,
    output wire                     above,
    output wire                     below_rearm,
    output wire                     enable
);
    assign polarity = residual[SAMPLE_W];
    // Low SAMPLE_W bits of -residual (two's complement: ~r + 1). This is exact
    // because |residual| <= 2^SAMPLE_W - 1 (residual >= -(2^SAMPLE_W - 1)).
    wire [SAMPLE_W-1:0] negated = (~residual[SAMPLE_W-1:0]) + {{(SAMPLE_W-1){1'b0}}, 1'b1};
    assign magnitude = polarity ? negated : residual[SAMPLE_W-1:0];

    assign enable = (threshold != {SAMPLE_W{1'b0}});
    assign above  = enable & (magnitude >= threshold);

    wire [SAMPLE_W-1:0] rearm_level =
        (hysteresis >= threshold) ? {{(SAMPLE_W-1){1'b0}}, 1'b1} : (threshold - hysteresis);
    assign below_rearm = (magnitude < rearm_level);
endmodule

module hbci_refractory_ctrl #(
    parameter integer REFR_W = 8
) (
    input  wire              primed,
    input  wire              enable,
    input  wire              armed,
    input  wire [REFR_W-1:0] refr_cnt,
    input  wire              above,
    input  wire              below_rearm,
    input  wire [REFR_W-1:0] cfg_refractory,
    output wire              fire,
    output wire              armed_next,
    output wire [REFR_W-1:0] refr_next
);
    wire refr_active = (refr_cnt != {REFR_W{1'b0}});
    assign fire       = primed & enable & armed & ~refr_active & above;
    assign armed_next = fire ? 1'b0 : (armed | below_rearm);
    assign refr_next  = fire        ? cfg_refractory :
                        refr_active ? (refr_cnt - {{(REFR_W-1){1'b0}}, 1'b1}) :
                                      {REFR_W{1'b0}};
endmodule

module hbci_timestamp #(
    parameter integer TS_W = 32
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            tick,
    input  wire            reject,
    output reg [TS_W-1:0]  ts_now,
    output reg [TS_W-1:0]  rejected
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ts_now   <= {TS_W{1'b0}};
            rejected <= {TS_W{1'b0}};
        end else begin
            if (tick)   ts_now   <= ts_now + {{(TS_W-1){1'b0}}, 1'b1};
            if (reject) rejected <= rejected + {{(TS_W-1){1'b0}}, 1'b1};
        end
    end
endmodule

module hbci_event_packer #(
    parameter integer CH_W     = 3,
    parameter integer SAMPLE_W = 16,
    parameter integer TS_W     = 32
) (
    input  wire                clk,
    input  wire                rst_n,
    input  wire                push,
    input  wire [CH_W-1:0]     in_channel,
    input  wire [TS_W-1:0]     in_timestamp,
    input  wire                in_polarity,
    input  wire [SAMPLE_W-1:0] in_magnitude,
    output reg                 ev_valid,
    input  wire                ev_ready,
    output reg [CH_W-1:0]      ev_channel,
    output reg [TS_W-1:0]      ev_timestamp,
    output reg                 ev_polarity,
    output reg [SAMPLE_W-1:0]  ev_magnitude,
    output reg [TS_W-1:0]      events,
    output wire                slot_free
);
    assign slot_free = ~ev_valid | ev_ready;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ev_valid     <= 1'b0;
            ev_channel   <= {CH_W{1'b0}};
            ev_timestamp <= {TS_W{1'b0}};
            ev_polarity  <= 1'b0;
            ev_magnitude <= {SAMPLE_W{1'b0}};
            events       <= {TS_W{1'b0}};
        end else if (push) begin
            ev_valid     <= 1'b1;
            ev_channel   <= in_channel;
            ev_timestamp <= in_timestamp;
            ev_polarity  <= in_polarity;
            ev_magnitude <= in_magnitude;
            events       <= events + {{(TS_W-1){1'b0}}, 1'b1};
        end else if (ev_ready) begin
            ev_valid     <= 1'b0;
        end
    end
endmodule

module hbci_readout_core #(
    parameter integer NUM_CH    = 8,    // number of input channels
    parameter integer CH_W      = 3,    // channel index width
    parameter integer SAMPLE_W  = 16,   // signed sample width
    parameter integer TS_W      = 32,   // sample index (timestamp) width
    parameter integer SEQ_W     = 16,   // per-type record sequence number width
    parameter integer FIFO_LOG2 = 4,    // record FIFO depth = 2^FIFO_LOG2
    parameter integer WIN_W     = 10,   // maximum energy window = 2^WIN_W samples
    parameter integer ACC_W     = 48,   // energy accumulator width
    parameter integer WIN_IDX_W = 16    // per-channel window index (frame identifier) width
) (
    input  wire                       clk,
    input  wire                       rst_n,

    // Configuration (quasi-static; sampled on use)
    input  wire                       cfg_session_en,   // 0: no records of any type are generated
    input  wire [1:0]                 cfg_mode,         // 0 EVENT, 1 RAW, 2 FEATURE, 3 HYBRID
    input  wire [SAMPLE_W-1:0]        cfg_threshold,    // legacy event core
    input  wire [SAMPLE_W-1:0]        cfg_hysteresis,   // legacy event core
    input  wire [7:0]                 cfg_refractory,   // legacy event core
    input  wire [3:0]                 cfg_alpha_shift,  // legacy event core
    input  wire signed [15:0]         cfg_b0,           // biquad coefficients, signed Q2.14
    input  wire signed [15:0]         cfg_b1,
    input  wire signed [15:0]         cfg_b2,
    input  wire signed [15:0]         cfg_a1,
    input  wire signed [15:0]         cfg_a2,
    input  wire [3:0]                 cfg_win_log2,     // window = 2^min(k, WIN_W) samples of a channel
    input  wire [5:0]                 cfg_energy_shift, // energy = sat32(sum >> shift)
    input  wire                       feat_sync,        // 1-cycle pulse: window counters of all channels <= 0

    // Sample input (ADC style: no back-pressure)
    input  wire                       in_valid,
    input  wire [CH_W-1:0]            in_channel,
    input  wire signed [SAMPLE_W-1:0] in_sample,

    // Record output (valid/ready)
    output wire                       rec_valid,
    input  wire                       rec_ready,
    output wire [1:0]                 rec_type,         // 0 RAW, 1 EVENT, 2 FEATURE
    output wire [CH_W-1:0]            rec_channel,
    output wire [3:0]                 rec_flags,        // bit0 sat, bit1 gap, bits 3:2 zero
    output wire [SEQ_W-1:0]           rec_seq,
    output wire [TS_W-1:0]            rec_ts,
    output wire [31:0]                rec_data,

    // Status counters
    output wire [TS_W-1:0]            stat_samples,     // accepted samples (== next sample index)
    output wire [TS_W-1:0]            stat_rejected,    // in_valid with channel >= NUM_CH
    output wire [31:0]                stat_drop_raw,
    output wire [31:0]                stat_drop_event,
    output wire [31:0]                stat_drop_feature,
    output reg  [31:0]                stat_event_missed,// samples u_event could not accept (stays 0)
    output wire [31:0]                stat_fifo_hwm,    // FIFO high-water mark, zero-extended
    // Feature tap for the on-chip AI decoder: before the record FIFO, not gated by
    // the output mode or the session (inference has its own enable).
    output wire                       ai_feat_valid,    // a window of channel ai_feat_ch completed this cycle
    output wire [CH_W-1:0]            ai_feat_ch,
    output wire [31:0]                ai_feat_energy,   // sat32(acc >> cfg_energy_shift), as in FEATURE records
    output wire [TS_W-1:0]            ai_feat_ts,       // index of the window's last sample
    output wire                       ai_feat_saturated,// FEATURE flags.sat of this window
    output wire [WIN_IDX_W-1:0]       ai_feat_win       // index of the completed window on that channel
);
    localparam integer FRAC_W = 8;      // legacy baseline fractional bits (v0.2 default)
    localparam integer REFR_W = 8;      // legacy refractory width (cfg_refractory[7:0])

    // ------------------------------------------------------------- accept
    wire [31:0] in_channel_x = {{(32-CH_W){1'b0}}, in_channel};
    wire ch_ok  = (in_channel_x < NUM_CH);
    wire accept = in_valid & ch_ok;      // updates channel state; index i = stat_samples
    wire reject = in_valid & ~ch_ok;     // ignored, counted in stat_rejected

    // Top-level sample index and rejected counter (reused v0.2 module)
    wire [TS_W-1:0] sample_idx;
    hbci_timestamp #(
        .TS_W(TS_W)
    ) u_ts (
        .clk(clk), .rst_n(rst_n),
        .tick(accept), .reject(reject),
        .ts_now(sample_idx), .rejected(stat_rejected)
    );
    assign stat_samples = sample_idx;

    // ------------------------------------------------- mode / session decode
    wire mode_event   = cfg_session_en & (cfg_mode == 2'd0);
    wire mode_raw     = cfg_session_en & cfg_mode[0];          // RAW (1) or HYBRID (3)
    wire mode_feature = cfg_session_en & cfg_mode[1];          // FEATURE (2) or HYBRID (3)

    // ------------------------------------------------------------ legacy path
    wire                ev_in_ready;
    wire                ev_valid;
    wire [CH_W-1:0]     ev_channel;
    wire [TS_W-1:0]     ev_timestamp;
    wire                ev_polarity;
    wire [SAMPLE_W-1:0] ev_magnitude;
    // u_event keeps its own counters; the top level uses u_ts instead.
    /* verilator lint_off UNUSEDSIGNAL */
    wire [TS_W-1:0]     ev_stat_samples, ev_stat_events, ev_stat_rejected;
    /* verilator lint_on UNUSEDSIGNAL */

    hbci_event_core #(
        .NUM_CH(NUM_CH), .CH_W(CH_W), .SAMPLE_W(SAMPLE_W),
        .FRAC_W(FRAC_W), .TS_W(TS_W), .REFR_W(REFR_W)
    ) u_event (
        .clk(clk), .rst_n(rst_n),
        .cfg_threshold(cfg_threshold), .cfg_hysteresis(cfg_hysteresis),
        .cfg_refractory(cfg_refractory), .cfg_alpha_shift(cfg_alpha_shift),
        .in_valid(in_valid), .in_ready(ev_in_ready),
        .in_channel(in_channel), .in_sample(in_sample),
        .ev_valid(ev_valid), .ev_ready(1'b1),               // always drained
        .ev_channel(ev_channel), .ev_timestamp(ev_timestamp),
        .ev_polarity(ev_polarity), .ev_magnitude(ev_magnitude),
        .stat_samples(ev_stat_samples), .stat_events(ev_stat_events),
        .stat_rejected(ev_stat_rejected)
    );

    // An EVENT record is generated in the cycle ev_valid is high (ev_ready = 1,
    // so each such cycle carries a distinct event).
    wire        event_gen  = ev_valid & mode_event;
    wire [31:0] event_data = {{(31-SAMPLE_W){1'b0}}, ev_polarity, ev_magnitude};

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            stat_event_missed <= 32'd0;
        else if (accept & ~ev_in_ready)
            stat_event_missed <= stat_event_missed + 32'd1;
    end

    // --------------------------------------------------------------- RAW path
    wire        raw_gen  = accept & mode_raw;
    wire [31:0] raw_data = {{(32-SAMPLE_W){in_sample[SAMPLE_W-1]}}, in_sample};

    // ----------------------------------------------------------- FEATURE path
    wire signed [SAMPLE_W-1:0] fs_x1, fs_x2, fs_y1, fs_y2;
    wire [ACC_W-1:0]           fs_acc;
    wire [WIN_W-1:0]           fs_cnt;
    wire                       fs_sat;
    wire [WIN_IDX_W-1:0]       fs_win;

    wire signed [SAMPLE_W-1:0] bq_y;
    wire                       bq_ysat;

    wire                       en_done;
    wire [31:0]                en_energy;
    wire                       en_feat_sat;
    wire [ACC_W-1:0]           en_acc_wr;
    wire [WIN_W-1:0]           en_cnt_wr;
    wire                       en_sat_wr;

    // Window index: advances when the window completes; feat_sync zeroes it (and
    // acc/cnt/sat) on every channel at once.
    localparam [WIN_IDX_W-1:0] WIN_ONE = {{(WIN_IDX_W-1){1'b0}}, 1'b1};
    wire [WIN_IDX_W-1:0] win_wr = en_done ? (fs_win + WIN_ONE) : fs_win;

    hbci_feature_state #(
        .NUM_CH(NUM_CH), .CH_W(CH_W), .SAMPLE_W(SAMPLE_W), .ACC_W(ACC_W), .WIN_W(WIN_W),
        .WIN_IDX_W(WIN_IDX_W)
    ) u_fstate (
        .clk(clk), .rst_n(rst_n),
        .ch(in_channel),
        .rd_x1(fs_x1), .rd_x2(fs_x2), .rd_y1(fs_y1), .rd_y2(fs_y2),
        .rd_acc(fs_acc), .rd_cnt(fs_cnt), .rd_sat(fs_sat), .rd_win(fs_win),
        .we(accept),                     // every accepted sample, regardless of session/mode
        .sync(feat_sync),
        .wr_x(in_sample), .wr_y(bq_y),
        .wr_acc(en_acc_wr), .wr_cnt(en_cnt_wr), .wr_sat(en_sat_wr), .wr_win(win_wr)
    );

    hbci_biquad #(
        .SAMPLE_W(SAMPLE_W), .COEF_W(16), .COEF_FRAC(14)
    ) u_biquad (
        .x(in_sample), .x1(fs_x1), .x2(fs_x2), .y1(fs_y1), .y2(fs_y2),
        .b0(cfg_b0), .b1(cfg_b1), .b2(cfg_b2), .a1(cfg_a1), .a2(cfg_a2),
        .y(bq_y), .ysat(bq_ysat)
    );

    hbci_band_energy #(
        .SAMPLE_W(SAMPLE_W), .ACC_W(ACC_W), .WIN_W(WIN_W)
    ) u_energy (
        .y(bq_y), .ysat(bq_ysat),
        .acc(fs_acc), .cnt(fs_cnt), .sat(fs_sat),
        .win_log2(cfg_win_log2), .energy_shift(cfg_energy_shift),
        .done(en_done), .energy(en_energy), .feat_sat(en_feat_sat),
        .acc_wr(en_acc_wr), .cnt_wr(en_cnt_wr), .sat_wr(en_sat_wr)
    );

    wire feat_gen = accept & en_done & mode_feature;

    // AI tap: every completed window, in every mode; suppressed in a sync cycle
    // (the window that ends in that cycle is discarded together with the counters).
    assign ai_feat_valid     = accept & en_done & ~feat_sync;
    assign ai_feat_ch        = in_channel;
    assign ai_feat_energy    = en_energy;
    assign ai_feat_ts        = sample_idx;
    assign ai_feat_saturated = en_feat_sat;
    assign ai_feat_win       = fs_win;

    // ------------------------------------------------------------- records
    wire [FIFO_LOG2:0] fifo_hwm;

    hbci_record_mux #(
        .CH_W(CH_W), .TS_W(TS_W), .SEQ_W(SEQ_W), .FIFO_LOG2(FIFO_LOG2)
    ) u_records (
        .clk(clk), .rst_n(rst_n),
        .raw_gen(raw_gen), .raw_ch(in_channel), .raw_ts(sample_idx), .raw_data(raw_data),
        .ev_gen(event_gen), .ev_ch(ev_channel), .ev_ts(ev_timestamp), .ev_data(event_data),
        .ft_gen(feat_gen), .ft_ch(in_channel), .ft_ts(sample_idx), .ft_data(en_energy),
        .ft_sat(en_feat_sat),
        .rec_valid(rec_valid), .rec_ready(rec_ready),
        .rec_type(rec_type), .rec_channel(rec_channel), .rec_flags(rec_flags),
        .rec_seq(rec_seq), .rec_ts(rec_ts), .rec_data(rec_data),
        .drop_raw(stat_drop_raw), .drop_event(stat_drop_event), .drop_feature(stat_drop_feature),
        .fifo_hwm(fifo_hwm)
    );
    assign stat_fifo_hwm = {{(31-FIFO_LOG2){1'b0}}, fifo_hwm};
endmodule

module hbci_feature_state #(
    parameter integer NUM_CH    = 8,
    parameter integer CH_W      = 3,
    parameter integer SAMPLE_W  = 16,
    parameter integer ACC_W     = 48,
    parameter integer WIN_W     = 10,
    parameter integer WIN_IDX_W = 16
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire [CH_W-1:0]            ch,
    output wire signed [SAMPLE_W-1:0] rd_x1,
    output wire signed [SAMPLE_W-1:0] rd_x2,
    output wire signed [SAMPLE_W-1:0] rd_y1,
    output wire signed [SAMPLE_W-1:0] rd_y2,
    output wire [ACC_W-1:0]           rd_acc,
    output wire [WIN_W-1:0]           rd_cnt,
    output wire                       rd_sat,
    output wire [WIN_IDX_W-1:0]       rd_win,
    input  wire                       we,
    input  wire                       sync,             // acc, cnt, sat, win of every channel <= 0
    input  wire signed [SAMPLE_W-1:0] wr_x,
    input  wire signed [SAMPLE_W-1:0] wr_y,
    input  wire [ACC_W-1:0]           wr_acc,
    input  wire [WIN_W-1:0]           wr_cnt,
    input  wire                       wr_sat,
    input  wire [WIN_IDX_W-1:0]       wr_win
);
    reg signed [SAMPLE_W-1:0] x1  [0:NUM_CH-1];
    reg signed [SAMPLE_W-1:0] x2  [0:NUM_CH-1];
    reg signed [SAMPLE_W-1:0] y1  [0:NUM_CH-1];
    reg signed [SAMPLE_W-1:0] y2  [0:NUM_CH-1];
    reg [ACC_W-1:0]           acc [0:NUM_CH-1];
    reg [WIN_W-1:0]           cnt [0:NUM_CH-1];
    reg [NUM_CH-1:0]          sat;
    reg [WIN_IDX_W-1:0]       win [0:NUM_CH-1];

    wire [31:0] ch_x = {{(32-CH_W){1'b0}}, ch};
    wire in_range = (ch_x < NUM_CH);
    assign rd_x1  = in_range ? x1[ch]  : {SAMPLE_W{1'b0}};
    assign rd_x2  = in_range ? x2[ch]  : {SAMPLE_W{1'b0}};
    assign rd_y1  = in_range ? y1[ch]  : {SAMPLE_W{1'b0}};
    assign rd_y2  = in_range ? y2[ch]  : {SAMPLE_W{1'b0}};
    assign rd_acc = in_range ? acc[ch] : {ACC_W{1'b0}};
    assign rd_cnt = in_range ? cnt[ch] : {WIN_W{1'b0}};
    assign rd_sat = in_range ? sat[ch] : 1'b0;
    assign rd_win = in_range ? win[ch] : {WIN_IDX_W{1'b0}};

    integer i;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < NUM_CH; i = i + 1) begin
                x1[i]  <= {SAMPLE_W{1'b0}};
                x2[i]  <= {SAMPLE_W{1'b0}};
                y1[i]  <= {SAMPLE_W{1'b0}};
                y2[i]  <= {SAMPLE_W{1'b0}};
                acc[i] <= {ACC_W{1'b0}};
                cnt[i] <= {WIN_W{1'b0}};
                win[i] <= {WIN_IDX_W{1'b0}};
            end
            sat <= {NUM_CH{1'b0}};
        end else begin
            if (we && in_range) begin
                x2[ch]  <= x1[ch];
                x1[ch]  <= wr_x;
                y2[ch]  <= y1[ch];
                y1[ch]  <= wr_y;
                acc[ch] <= wr_acc;
                cnt[ch] <= wr_cnt;
                sat[ch] <= wr_sat;
                win[ch] <= wr_win;
            end
            if (sync) begin                  // wins over the write of the same cycle
                for (i = 0; i < NUM_CH; i = i + 1) begin
                    acc[i] <= {ACC_W{1'b0}};
                    cnt[i] <= {WIN_W{1'b0}};
                    win[i] <= {WIN_IDX_W{1'b0}};
                end
                sat <= {NUM_CH{1'b0}};
            end
        end
    end
endmodule

module hbci_biquad #(
    parameter integer SAMPLE_W  = 16,
    parameter integer COEF_W    = 16,
    parameter integer COEF_FRAC = 14
) (
    input  wire signed [SAMPLE_W-1:0] x,
    input  wire signed [SAMPLE_W-1:0] x1,
    input  wire signed [SAMPLE_W-1:0] x2,
    input  wire signed [SAMPLE_W-1:0] y1,
    input  wire signed [SAMPLE_W-1:0] y2,
    input  wire signed [COEF_W-1:0]   b0,
    input  wire signed [COEF_W-1:0]   b1,
    input  wire signed [COEF_W-1:0]   b2,
    input  wire signed [COEF_W-1:0]   a1,
    input  wire signed [COEF_W-1:0]   a2,
    output wire signed [SAMPLE_W-1:0] y,
    output wire                       ysat
);
    localparam integer P_W  = SAMPLE_W + COEF_W + 3;   // 35 bits for 16 x 16
    localparam integer YF_W = P_W - COEF_FRAC;         // width of y_full (21 bits)

    // Operands sign-extended to the full accumulator width, so every product
    // and sum below is exact two's-complement arithmetic in P_W bits.
    wire signed [P_W-1:0] sx  = {{(P_W-SAMPLE_W){x[SAMPLE_W-1]}},  x};
    wire signed [P_W-1:0] sx1 = {{(P_W-SAMPLE_W){x1[SAMPLE_W-1]}}, x1};
    wire signed [P_W-1:0] sx2 = {{(P_W-SAMPLE_W){x2[SAMPLE_W-1]}}, x2};
    wire signed [P_W-1:0] sy1 = {{(P_W-SAMPLE_W){y1[SAMPLE_W-1]}}, y1};
    wire signed [P_W-1:0] sy2 = {{(P_W-SAMPLE_W){y2[SAMPLE_W-1]}}, y2};
    wire signed [P_W-1:0] cb0 = {{(P_W-COEF_W){b0[COEF_W-1]}}, b0};
    wire signed [P_W-1:0] cb1 = {{(P_W-COEF_W){b1[COEF_W-1]}}, b1};
    wire signed [P_W-1:0] cb2 = {{(P_W-COEF_W){b2[COEF_W-1]}}, b2};
    wire signed [P_W-1:0] ca1 = {{(P_W-COEF_W){a1[COEF_W-1]}}, a1};
    wire signed [P_W-1:0] ca2 = {{(P_W-COEF_W){a2[COEF_W-1]}}, a2};

    wire signed [P_W-1:0] m_b0 = cb0 * sx;
    wire signed [P_W-1:0] m_b1 = cb1 * sx1;
    wire signed [P_W-1:0] m_b2 = cb2 * sx2;
    wire signed [P_W-1:0] m_a1 = ca1 * sy1;
    wire signed [P_W-1:0] m_a2 = ca2 * sy2;
    wire signed [P_W-1:0] p    = m_b0 + m_b1 + m_b2 - m_a1 - m_a2;

    // Rounding constant 2^(COEF_FRAC-1); the low COEF_FRAC bits of p_r are
    // discarded by the arithmetic shift (floor), so they are intentionally unused.
    localparam [P_W-1:0] ROUND = {{(P_W-COEF_FRAC){1'b0}}, 1'b1, {(COEF_FRAC-1){1'b0}}};
    /* verilator lint_off UNUSEDSIGNAL */
    wire signed [P_W-1:0] p_r  = p + ROUND;
    /* verilator lint_on UNUSEDSIGNAL */
    wire signed [YF_W-1:0] y_full = p_r[P_W-1:COEF_FRAC];   // == p_r >>> COEF_FRAC

    // y_full fits SAMPLE_W bits iff its top YF_W-SAMPLE_W+1 bits are all equal.
    wire [YF_W-SAMPLE_W:0] top = y_full[YF_W-1:SAMPLE_W-1];
    wire fits = (&top) | ~(|top);
    localparam [SAMPLE_W-1:0] Y_MAX = {1'b0, {(SAMPLE_W-1){1'b1}}};
    localparam [SAMPLE_W-1:0] Y_MIN = {1'b1, {(SAMPLE_W-1){1'b0}}};
    assign y    = fits ? y_full[SAMPLE_W-1:0] : (y_full[YF_W-1] ? Y_MIN : Y_MAX);
    assign ysat = ~fits;
endmodule

module hbci_band_energy #(
    parameter integer SAMPLE_W = 16,
    parameter integer ACC_W    = 48,
    parameter integer WIN_W    = 10
) (
    input  wire signed [SAMPLE_W-1:0] y,
    input  wire                       ysat,
    input  wire [ACC_W-1:0]           acc,
    input  wire [WIN_W-1:0]           cnt,
    input  wire                       sat,
    input  wire [3:0]                 win_log2,
    input  wire [5:0]                 energy_shift,
    output wire                       done,
    output wire [31:0]                energy,
    output wire                       feat_sat,
    output wire [ACC_W-1:0]           acc_wr,
    output wire [WIN_W-1:0]           cnt_wr,
    output wire                       sat_wr
);
    localparam integer SQ_W = 2 * SAMPLE_W - 1;

    // y*y <= 2^(2*SAMPLE_W-2) (y = -2^(SAMPLE_W-1)), so the top bit of the
    // 2*SAMPLE_W-bit signed product is always 0 and is intentionally unused.
    wire signed [2*SAMPLE_W-1:0] y_x = {{SAMPLE_W{y[SAMPLE_W-1]}}, y};
    /* verilator lint_off UNUSEDSIGNAL */
    wire signed [2*SAMPLE_W-1:0] sq_full = y_x * y_x;
    /* verilator lint_on UNUSEDSIGNAL */
    wire [SQ_W-1:0]  sq       = sq_full[SQ_W-1:0];
    wire [ACC_W-1:0] acc_next = acc + {{(ACC_W-SQ_W){1'b0}}, sq};

    // Window: k = min(win_log2, WIN_W); win - 1 = WIN_W-bit mask of k ones.
    wire [31:0]      wl_x   = {28'd0, win_log2};
    wire [31:0]      k      = (wl_x > WIN_W) ? WIN_W : wl_x;
    wire [WIN_W-1:0] win_m1 = ~({WIN_W{1'b1}} << k);
    assign done = (cnt >= win_m1);

    // Output scaling and saturation to 32 bits.
    wire [ACC_W-1:0] shifted = acc_next >> energy_shift;
    wire             esat;
    generate
        if (ACC_W > 32) begin : g_sat
            assign esat   = |shifted[ACC_W-1:32];
            assign energy = esat ? 32'hFFFF_FFFF : shifted[31:0];
        end else begin : g_nosat
            assign esat   = 1'b0;
            assign energy = {{(32-ACC_W){1'b0}}, shifted};
        end
    endgenerate

    assign feat_sat = sat | ysat | esat;
    assign acc_wr   = done ? {ACC_W{1'b0}} : acc_next;
    assign cnt_wr   = done ? {WIN_W{1'b0}} : (cnt + {{(WIN_W-1){1'b0}}, 1'b1});
    assign sat_wr   = done ? 1'b0 : (sat | ysat);
endmodule

module hbci_record_mux #(
    parameter integer CH_W      = 3,
    parameter integer TS_W      = 32,
    parameter integer SEQ_W     = 16,
    parameter integer FIFO_LOG2 = 4
) (
    input  wire                 clk,
    input  wire                 rst_n,
    input  wire                 raw_gen,
    input  wire [CH_W-1:0]      raw_ch,
    input  wire [TS_W-1:0]      raw_ts,
    input  wire [31:0]          raw_data,
    input  wire                 ev_gen,
    input  wire [CH_W-1:0]      ev_ch,
    input  wire [TS_W-1:0]      ev_ts,
    input  wire [31:0]          ev_data,
    input  wire                 ft_gen,
    input  wire [CH_W-1:0]      ft_ch,
    input  wire [TS_W-1:0]      ft_ts,
    input  wire [31:0]          ft_data,
    input  wire                 ft_sat,
    output wire                 rec_valid,
    input  wire                 rec_ready,
    output wire [1:0]           rec_type,
    output wire [CH_W-1:0]      rec_channel,
    output wire [3:0]           rec_flags,
    output wire [SEQ_W-1:0]     rec_seq,
    output wire [TS_W-1:0]      rec_ts,
    output wire [31:0]          rec_data,
    output reg  [31:0]          drop_raw,
    output reg  [31:0]          drop_event,
    output reg  [31:0]          drop_feature,
    output reg  [FIFO_LOG2:0]   fifo_hwm
);
    localparam integer DEPTH   = 1 << FIFO_LOG2;
    localparam integer ENTRY_W = 2 + CH_W + 4 + SEQ_W + TS_W + 32;
    localparam [1:0] T_RAW = 2'd0, T_EVENT = 2'd1, T_FEATURE = 2'd2;
    localparam [SEQ_W-1:0]   SEQ_ONE = {{(SEQ_W-1){1'b0}}, 1'b1};
    localparam [FIFO_LOG2:0] CNT_ONE = {{FIFO_LOG2{1'b0}}, 1'b1};
    localparam [FIFO_LOG2-1:0] PTR_ONE = {{(FIFO_LOG2-1){1'b0}}, 1'b1};

    // ------------------------------------------------------ pending registers
    reg              p_raw_v, p_raw_gap;
    reg [CH_W-1:0]   p_raw_ch;
    reg [TS_W-1:0]   p_raw_ts;
    reg [31:0]       p_raw_data;
    reg [SEQ_W-1:0]  p_raw_seq;

    reg              p_ev_v, p_ev_gap;
    reg [CH_W-1:0]   p_ev_ch;
    reg [TS_W-1:0]   p_ev_ts;
    reg [31:0]       p_ev_data;
    reg [SEQ_W-1:0]  p_ev_seq;

    reg              p_ft_v, p_ft_gap, p_ft_sat;
    reg [CH_W-1:0]   p_ft_ch;
    reg [TS_W-1:0]   p_ft_ts;
    reg [31:0]       p_ft_data;
    reg [SEQ_W-1:0]  p_ft_seq;

    reg [SEQ_W-1:0]  seq_raw, seq_ev, seq_ft;      // next sequence number per type
    reg              gp_raw, gp_ev, gp_ft;         // gap_pending per type

    // --------------------------------------------------------------- FIFO
    reg [ENTRY_W-1:0]   mem [0:DEPTH-1];
    reg [FIFO_LOG2-1:0] wr_ptr, rd_ptr;
    reg [FIFO_LOG2:0]   count;

    wire fifo_full = count[FIFO_LOG2];             // count <= DEPTH, so MSB set <=> full
    assign rec_valid = (count != {(FIFO_LOG2+1){1'b0}});
    wire pop = rec_valid & rec_ready;

    // ------------------------------------------------------------ arbiter
    wire mv_ev  = p_ev_v & ~fifo_full;
    wire mv_ft  = p_ft_v & ~p_ev_v & ~fifo_full;
    wire mv_raw = p_raw_v & ~p_ev_v & ~p_ft_v & ~fifo_full;
    wire push   = mv_ev | mv_ft | mv_raw;

    wire [ENTRY_W-1:0] e_ev  = {T_EVENT,   p_ev_ch,  2'b00, p_ev_gap,  1'b0,     p_ev_seq,  p_ev_ts,  p_ev_data};
    wire [ENTRY_W-1:0] e_ft  = {T_FEATURE, p_ft_ch,  2'b00, p_ft_gap,  p_ft_sat, p_ft_seq,  p_ft_ts,  p_ft_data};
    wire [ENTRY_W-1:0] e_raw = {T_RAW,     p_raw_ch, 2'b00, p_raw_gap, 1'b0,     p_raw_seq, p_raw_ts, p_raw_data};
    wire [ENTRY_W-1:0] entry = mv_ev ? e_ev : (mv_ft ? e_ft : e_raw);

    wire [FIFO_LOG2:0] count_next = push ? (pop ? count : count + CNT_ONE)
                                         : (pop ? count - CNT_ONE : count);

    // FIFO head
    wire [ENTRY_W-1:0] head = mem[rd_ptr];
    assign rec_data    = head[31:0];
    assign rec_ts      = head[32 +: TS_W];
    assign rec_seq     = head[32 + TS_W +: SEQ_W];
    assign rec_flags   = head[32 + TS_W + SEQ_W +: 4];
    assign rec_channel = head[36 + TS_W + SEQ_W +: CH_W];
    assign rec_type    = head[36 + TS_W + SEQ_W + CH_W +: 2];

    integer i;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < DEPTH; i = i + 1) mem[i] <= {ENTRY_W{1'b0}};
            wr_ptr <= {FIFO_LOG2{1'b0}};
            rd_ptr <= {FIFO_LOG2{1'b0}};
            count  <= {(FIFO_LOG2+1){1'b0}};
            fifo_hwm <= {(FIFO_LOG2+1){1'b0}};
        end else begin
            if (push) begin
                mem[wr_ptr] <= entry;
                wr_ptr <= wr_ptr + PTR_ONE;
            end
            if (pop) rd_ptr <= rd_ptr + PTR_ONE;
            count <= count_next;
            if (count_next > fifo_hwm) fifo_hwm <= count_next;
        end
    end

    // ------------------------------------------- RAW pending register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_raw_v <= 1'b0; p_raw_gap <= 1'b0; p_raw_ch <= {CH_W{1'b0}};
            p_raw_ts <= {TS_W{1'b0}}; p_raw_data <= 32'd0; p_raw_seq <= {SEQ_W{1'b0}};
            seq_raw <= {SEQ_W{1'b0}}; gp_raw <= 1'b0; drop_raw <= 32'd0;
        end else if (raw_gen) begin
            seq_raw <= seq_raw + SEQ_ONE;
            if (p_raw_v & ~mv_raw) begin              // register still full: drop
                drop_raw <= drop_raw + 32'd1;
                gp_raw   <= 1'b1;
            end else begin                            // accept
                p_raw_v <= 1'b1; p_raw_gap <= gp_raw; p_raw_ch <= raw_ch;
                p_raw_ts <= raw_ts; p_raw_data <= raw_data; p_raw_seq <= seq_raw;
                gp_raw  <= 1'b0;
            end
        end else if (mv_raw) begin
            p_raw_v <= 1'b0;
        end
    end

    // ----------------------------------------- EVENT pending register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_ev_v <= 1'b0; p_ev_gap <= 1'b0; p_ev_ch <= {CH_W{1'b0}};
            p_ev_ts <= {TS_W{1'b0}}; p_ev_data <= 32'd0; p_ev_seq <= {SEQ_W{1'b0}};
            seq_ev <= {SEQ_W{1'b0}}; gp_ev <= 1'b0; drop_event <= 32'd0;
        end else if (ev_gen) begin
            seq_ev <= seq_ev + SEQ_ONE;
            if (p_ev_v & ~mv_ev) begin
                drop_event <= drop_event + 32'd1;
                gp_ev      <= 1'b1;
            end else begin
                p_ev_v <= 1'b1; p_ev_gap <= gp_ev; p_ev_ch <= ev_ch;
                p_ev_ts <= ev_ts; p_ev_data <= ev_data; p_ev_seq <= seq_ev;
                gp_ev  <= 1'b0;
            end
        end else if (mv_ev) begin
            p_ev_v <= 1'b0;
        end
    end

    // --------------------------------------- FEATURE pending register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_ft_v <= 1'b0; p_ft_gap <= 1'b0; p_ft_sat <= 1'b0; p_ft_ch <= {CH_W{1'b0}};
            p_ft_ts <= {TS_W{1'b0}}; p_ft_data <= 32'd0; p_ft_seq <= {SEQ_W{1'b0}};
            seq_ft <= {SEQ_W{1'b0}}; gp_ft <= 1'b0; drop_feature <= 32'd0;
        end else if (ft_gen) begin
            seq_ft <= seq_ft + SEQ_ONE;
            if (p_ft_v & ~mv_ft) begin
                drop_feature <= drop_feature + 32'd1;
                gp_ft        <= 1'b1;
            end else begin
                p_ft_v <= 1'b1; p_ft_gap <= gp_ft; p_ft_sat <= ft_sat; p_ft_ch <= ft_ch;
                p_ft_ts <= ft_ts; p_ft_data <= ft_data; p_ft_seq <= seq_ft;
                gp_ft  <= 1'b0;
            end
        end else if (mv_ft) begin
            p_ft_v <= 1'b0;
        end
    end
endmodule

module hbci_log_energy (
    input  wire [31:0] e,
    output wire [10:0] l
);
    wire        n4 = |e[31:16];
    wire [15:0] s4 = n4 ? e[31:16] : e[15:0];
    wire        n3 = |s4[15:8];
    wire [7:0]  s3 = n3 ? s4[15:8] : s4[7:0];
    wire        n2 = |s3[7:4];
    wire [3:0]  s2 = n2 ? s3[7:4] : s3[3:0];
    wire        n1 = |s2[3:2];
    // s1[0] and norm[31], norm[24:0] are intentionally unused (only the leading one's
    // position and the six bits below it are needed).
    /* verilator lint_off UNUSEDSIGNAL */
    wire [1:0]  s1 = n1 ? s2[3:2] : s2[1:0];
    wire [31:0] norm;
    /* verilator lint_on UNUSEDSIGNAL */
    wire        n0 = s1[1];
    wire [4:0]  n  = {n4, n3, n2, n1, n0};
    wire [4:0]  sh = 5'd31 - n;
    assign norm = e << sh;                            // leading one moved to bit 31
    assign l = (e == 32'd0) ? 11'd0 : {n, norm[30:25]};
endmodule

module hbci_feat_quant (
    input  wire [31:0]       energy,
    input  wire [11:0]       centre,
    input  wire [2:0]        qshift,
    input  wire              enabled,
    output wire [10:0]       l,
    output wire signed [7:0] x
);
    hbci_log_energy u_log (.e(energy), .l(l));
    wire signed [13:0] diff = $signed({3'b000, l}) - $signed({2'b00, centre});   // -4095 .. 2047
    wire signed [13:0] sh   = diff >>> qshift;
    wire signed [7:0]  xs   = (sh > 14'sd127) ? 8'sd127 : (sh < -14'sd128) ? -8'sd128 : sh[7:0];
    assign x = enabled ? xs : 8'sd0;
endmodule

module hbci_frame_collector #(
    parameter integer TS_W      = 32,
    parameter integer WIN_IDX_W = 16
) (
    input  wire                 clk,
    input  wire                 rst_n,
    input  wire                 enable,           // 0: no frame is open (cleared)
    input  wire                 sync,             // clears the open frame
    input  wire [7:0]           ch_mask,
    input  wire [TS_W-1:0]      frame_span,
    input  wire                 feat_valid,
    input  wire [2:0]           feat_ch,
    input  wire signed [7:0]    feat_x,
    input  wire [TS_W-1:0]      feat_ts,
    input  wire                 feat_sat,
    input  wire [WIN_IDX_W-1:0] feat_win,
    output reg                  frame_valid,      // one-cycle pulse, frame_* valid with it
    output reg  [WIN_IDX_W-1:0] frame_id,
    output reg  [TS_W-1:0]      frame_ts,         // ts of the last feature of the frame
    output reg  [63:0]          frame_x,          // x_7 .. x_0, int8 each
    output reg  [7:0]           frame_sat,
    output reg  [31:0]          stat_frames,
    output reg  [31:0]          stat_incomplete,
    output reg  [31:0]          stat_dup,
    output reg  [31:0]          stat_late,
    output reg  [31:0]          stat_span,
    output reg  [7:0]           last_missing      // channels missing from the last abandoned frame
`ifdef FORMAL
    , output wire                f_open,           // formal probes (SymbiYosys only)
    output wire [7:0]            f_seen,
    output wire [WIN_IDX_W-1:0]  f_id
`endif
);
    reg                  open;
    reg [WIN_IDX_W-1:0]  id;
    reg [TS_W-1:0]       ts_first;
    reg [7:0]            seen;
    reg [7:0]            sat;
    reg signed [7:0]     xr [0:7];

`ifdef FORMAL
    assign f_open = open;
    assign f_seen = seen;
    assign f_id   = id;
`endif
    wire                 act      = feat_valid & enable & ~sync & ch_mask[feat_ch];
    wire [WIN_IDX_W-1:0] d        = feat_win - id;
    wire                 same     = open & (d == {WIN_IDX_W{1'b0}});
    wire                 late     = open & d[WIN_IDX_W-1];
    wire                 newer    = open & ~d[WIN_IDX_W-1] & (d != {WIN_IDX_W{1'b0}});
    wire                 dup      = same & seen[feat_ch];
    wire [TS_W-1:0]      span_now = feat_ts - ts_first;
    wire                 span_bad = same & ~dup & (span_now > frame_span);
    wire                 restart  = ~open | newer | dup | span_bad;    // this feature opens a new frame
    wire                 abandon  = act & (newer | dup | span_bad);
    wire                 store    = act & ~late;
    wire [7:0]           chbit    = 8'b0000_0001 << feat_ch;
    wire [7:0]           seen_base = restart ? 8'd0 : seen;
    wire [7:0]           seen_next = seen_base | chbit;
    wire [7:0]           sat_base  = restart ? 8'd0 : sat;
    wire [7:0]           sat_next  = sat_base | (feat_sat ? chbit : 8'd0);
    wire                 complete  = store & ((seen_next & ch_mask) == ch_mask);

    integer k;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            open <= 1'b0; id <= {WIN_IDX_W{1'b0}}; ts_first <= {TS_W{1'b0}};
            seen <= 8'd0; sat <= 8'd0;
            for (k = 0; k < 8; k = k + 1) xr[k] <= 8'sd0;
            frame_valid <= 1'b0; frame_id <= {WIN_IDX_W{1'b0}}; frame_ts <= {TS_W{1'b0}};
            frame_x <= 64'd0; frame_sat <= 8'd0;
            stat_frames <= 32'd0; stat_incomplete <= 32'd0; stat_dup <= 32'd0;
            stat_late <= 32'd0; stat_span <= 32'd0; last_missing <= 8'd0;
        end else begin
            frame_valid <= 1'b0;
            if (act & late)        stat_late <= stat_late + 32'd1;
            if (act & newer)       stat_incomplete <= stat_incomplete + 32'd1;
            if (act & dup)         stat_dup <= stat_dup + 32'd1;
            if (act & span_bad)    stat_span <= stat_span + 32'd1;
            if (abandon)           last_missing <= ch_mask & ~seen;
            if (store) begin
                if (restart) begin
                    id <= feat_win;
                    ts_first <= feat_ts;
                    for (k = 0; k < 8; k = k + 1) xr[k] <= (k[2:0] == feat_ch) ? feat_x : 8'sd0;
                end else begin
                    xr[feat_ch] <= feat_x;
                end
                seen <= seen_next;
                sat  <= sat_next;
                open <= ~complete;
            end
            if (complete) begin
                stat_frames <= stat_frames + 32'd1;
                frame_valid <= 1'b1;
                frame_id    <= restart ? feat_win : id;
                frame_ts    <= feat_ts;
                frame_sat   <= sat_next;
                for (k = 0; k < 8; k = k + 1)
                    frame_x[8*k +: 8] <= (k[2:0] == feat_ch) ? feat_x : (seen_base[k] ? xr[k] : 8'sd0);
            end
            if (!enable || sync) begin
                open <= 1'b0;
                seen <= 8'd0;
                frame_valid <= 1'b0;
            end
        end
    end
endmodule

module hbci_model_store #(
    parameter integer NH = 4,
    parameter integer NO = 2
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        ai_en,            // writes are rejected while 1
    input  wire        we,
    input  wire [5:0]  addr,             // 0..45 (others ignored)
    input  wire [31:0] wdata,
    output wire [31:0] rdata,            // word at addr (undefined while busy)
    input  wire        crc_we,
    input  wire [31:0] crc_wdata,
    output reg  [31:0] crc_expected,
    input  wire        verify,           // start the CRC check
    input  wire        clear_rej,
    output reg         valid,
    output reg         error,
    output reg         busy,
    output reg         rejected,         // sticky: a write was rejected (ai_en = 1 or busy)
    output reg  [31:0] stat_wr_rej,
    // model contents for the engine
    output reg  [NH*64-1:0] w1_flat,     // w1[h][c] at bits (h*8+c)*8 +: 8
    output reg  [NO*64-1:0] w2_flat,     // w2[o][k] at bits (o*8+k)*8 +: 8
    output reg  [NH*32-1:0] b1_flat,
    output reg  [NO*32-1:0] b2_flat,
    output reg  [95:0]      centre_flat, // centre[c] at bits c*12 +: 12
    output reg  [23:0]      qshift_flat, // qshift[c] at bits c*3 +: 3
    output wire [4:0]       s1,
    output wire             linear,
    output wire [15:0]      model_id
);
    localparam [31:0] CRC_POLY = 32'hEDB8_8320;
    localparam [31:0] NH32 = NH;
    localparam [31:0] NO32 = NO;

    reg [31:0] cfg;                        // bits 4:0 s1, 8 linear, 31:16 model_id
    assign s1       = cfg[4:0];
    assign linear   = cfg[8];
    assign model_id = cfg[31:16];

    // ------------------------------------------------------------- read mux
    reg [5:0]  crc_addr;
    reg [1:0]  crc_byte;
    reg [31:0] crc;
    wire [5:0] raddr = busy ? crc_addr : addr;
    wire       r_w1 = (raddr < 6'd16);
    wire       r_w2 = (raddr >= 6'd16) & (raddr < 6'd24);
    wire       r_b1 = (raddr >= 6'd24) & (raddr < 6'd32);
    wire       r_b2 = (raddr >= 6'd32) & (raddr < 6'd36);
    wire       r_ct = (raddr >= 6'd36) & (raddr < 6'd44);
    wire       r_cf = (raddr == 6'd44);
    wire [2:0] r_ch = raddr[2:0] + 3'd4;                   // channel of a centre word: raddr - 36
    wire       r_w1_ok = r_w1 & ({28'd0, raddr[4:1]} < NH32);
    wire       r_w2_ok = r_w2 & ({30'd0, raddr[2:1]} < NO32);
    wire       r_b1_ok = r_b1 & ({29'd0, raddr[2:0]} < NH32);
    wire       r_b2_ok = r_b2 & ({30'd0, raddr[1:0]} < NO32);
    wire [31:0] rword =
        r_w1_ok ? w1_flat[raddr[4:0]*32 +: 32] :
        r_w2_ok ? w2_flat[raddr[2:0]*32 +: 32] :
        r_b1_ok ? b1_flat[raddr[2:0]*32 +: 32] :
        r_b2_ok ? b2_flat[raddr[1:0]*32 +: 32] :
        r_ct    ? {17'd0, qshift_flat[r_ch*3 +: 3], centre_flat[r_ch*12 +: 12]} :
        r_cf    ? cfg : 32'd0;
    assign rdata = rword;

    // ---------------------------------------------------------------- CRC-32
    function [31:0] crc_byte_step;
        input [31:0] c;
        input [7:0]  b;
        reg   [31:0] t;
        integer j;
        begin
            t = c ^ {24'd0, b};
            for (j = 0; j < 8; j = j + 1)
                t = t[0] ? ((t >> 1) ^ CRC_POLY) : (t >> 1);
            crc_byte_step = t;
        end
    endfunction

    wire [7:0]  crc_in   = rword[8*crc_byte +: 8];
    wire [31:0] crc_next = crc_byte_step(crc, crc_in);
    wire        crc_last = (crc_addr == 6'd45) & (crc_byte == 2'd3);
    wire        wr_ok    = we & ~ai_en & ~busy & (addr < 6'd46);
    wire        w_w1_ok  = (addr < 6'd16) & ({28'd0, addr[4:1]} < NH32);
    wire        w_w2_ok  = (addr >= 6'd16) & (addr < 6'd24) & ({30'd0, addr[2:1]} < NO32);
    wire        w_b1_ok  = (addr >= 6'd24) & (addr < 6'd32) & ({29'd0, addr[2:0]} < NH32);
    wire        w_b2_ok  = (addr >= 6'd32) & (addr < 6'd36) & ({30'd0, addr[1:0]} < NO32);
    wire        w_ct     = (addr >= 6'd36) & (addr < 6'd44);
    wire [2:0]  w_ch     = addr[2:0] + 3'd4;               // channel of a centre word: addr - 36

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            w1_flat <= {(NH*64){1'b0}};
            w2_flat <= {(NO*64){1'b0}};
            b1_flat <= {(NH*32){1'b0}};
            b2_flat <= {(NO*32){1'b0}};
            centre_flat <= 96'd0;
            qshift_flat <= 24'd0;
            cfg <= 32'd0;
            crc_expected <= 32'd0;
            crc_addr <= 6'd0; crc_byte <= 2'd0; crc <= 32'hFFFF_FFFF;
            valid <= 1'b0; error <= 1'b0; busy <= 1'b0; rejected <= 1'b0; stat_wr_rej <= 32'd0;
        end else begin
            if (clear_rej) rejected <= 1'b0;
            if (we & (ai_en | busy)) begin
                rejected <= 1'b1;
                stat_wr_rej <= stat_wr_rej + 32'd1;
            end
            if (wr_ok) begin
                valid <= 1'b0;
                error <= 1'b0;
                if (w_w1_ok) w1_flat[addr[4:0]*32 +: 32] <= wdata;
                if (w_w2_ok) w2_flat[addr[2:0]*32 +: 32] <= wdata;
                if (w_b1_ok) b1_flat[addr[2:0]*32 +: 32] <= wdata;
                if (w_b2_ok) b2_flat[addr[1:0]*32 +: 32] <= wdata;
                if (w_ct) begin
                    centre_flat[w_ch*12 +: 12] <= wdata[11:0];
                    qshift_flat[w_ch*3 +: 3]   <= wdata[14:12];
                end
                if (addr == 6'd44) cfg <= {wdata[31:16], 7'd0, wdata[8], 3'd0, wdata[4:0]};
            end
            if (crc_we & ~busy) begin
                crc_expected <= crc_wdata;
                valid <= 1'b0;
                error <= 1'b0;
            end
            if (busy) begin
                crc <= crc_next;
                crc_byte <= crc_byte + 2'd1;
                if (crc_byte == 2'd3) crc_addr <= crc_addr + 6'd1;
                if (crc_last) begin
                    busy  <= 1'b0;
                    valid <= ((crc_next ^ 32'hFFFF_FFFF) == crc_expected);
                    error <= ((crc_next ^ 32'hFFFF_FFFF) != crc_expected);
                end
            end else if (verify & ~ai_en) begin
                busy <= 1'b1;
                valid <= 1'b0;
                error <= 1'b0;
                crc <= 32'hFFFF_FFFF;
                crc_addr <= 6'd0;
                crc_byte <= 2'd0;
            end
        end
    end
endmodule

module hbci_mlp_engine #(
    parameter integer NH        = 4,
    parameter integer NO        = 2,
    parameter integer TS_W      = 32,
    parameter integer WIN_IDX_W = 16
) (
    input  wire                 clk,
    input  wire                 rst_n,
    input  wire                 enable,           // 0: abort, back to idle
    input  wire                 start,
    output wire                 busy,
    input  wire [63:0]          in_x,
    input  wire [WIN_IDX_W-1:0] in_frame_id,
    input  wire [TS_W-1:0]      in_ts,
    input  wire [7:0]           in_sat,
    input  wire                 linear,
    input  wire [4:0]           s1,
    input  wire [NH*64-1:0]     w1_flat,
    input  wire [NO*64-1:0]     w2_flat,
    input  wire [NH*32-1:0]     b1_flat,
    input  wire [NO*32-1:0]     b2_flat,
    output reg                  done,             // one-cycle pulse, out_* valid with it and after
    output reg  [1:0]           out_cls,
    output reg  [31:0]          out_margin,
    output reg  [TS_W-1:0]      out_ts,
    output reg  [WIN_IDX_W-1:0] out_frame_id,
    output reg  [7:0]           out_sat,
    output reg  [63:0]          out_x,            // loaded at start (with out_ts/out_frame_id/out_sat)
    output reg  [63:0]          out_h,            // h_7 .. h_0 (0 for rows >= NH); updated at completion
    output reg  [127:0]         out_logit         // sat32(logit_3 .. logit_0) (0 for rows >= NO); at completion
);
    localparam [1:0] S_IDLE = 2'd0, S_L1 = 2'd1, S_L2 = 2'd2, S_FIN = 2'd3;
    localparam [31:0] NH_M1_32 = NH - 1;
    localparam [31:0] NO_M1_32 = NO - 1;
    localparam [2:0]  NH_M1 = NH_M1_32[2:0];
    localparam [2:0]  NO_M1 = NO_M1_32[2:0];
    reg [1:0]          state;
    reg [2:0]          row;
    reg [2:0]          col;
    reg signed [33:0]  acc;
    reg signed [7:0]   x [0:7];
    reg [6:0]          h [0:7];
    reg signed [33:0]  logit [0:3];
    assign busy = (state != S_IDLE);

    // operands
    wire [2:0] n2_last = linear ? 3'd7 : NH_M1;
    wire [5:0] w1_idx = {row, col};
    wire [5:0] w2_idx = {row, col};
    wire signed [7:0] a_l1 = x[col];
    wire signed [7:0] a_l2 = linear ? x[col] : $signed({1'b0, h[col]});
    wire signed [7:0] w_l1 = $signed(w1_flat[8*w1_idx +: 8]);
    wire signed [7:0] w_l2 = $signed(w2_flat[8*w2_idx +: 8]);
    wire signed [7:0] a = (state == S_L1) ? a_l1 : a_l2;
    wire signed [7:0] w = (state == S_L1) ? w_l1 : w_l2;
    wire signed [15:0] prod = a * w;
    wire signed [33:0] sum  = acc + {{18{prod[15]}}, prod};
    wire signed [33:0] relu_in = sum >>> s1;
    wire [6:0] relu = (relu_in < 34'sd0) ? 7'd0 : (relu_in > 34'sd127) ? 7'd127 : relu_in[6:0];
    wire [2:0] row_p1 = row + 3'd1;
    wire signed [31:0] b1_next = $signed(b1_flat[32*row_p1 +: 32]);
    wire signed [31:0] b2_next = $signed(b2_flat[32*row_p1 +: 32]);
    wire signed [31:0] b1_0 = $signed(b1_flat[31:0]);
    wire signed [31:0] b2_0 = $signed(b2_flat[31:0]);

    // argmax and margin over the NO logits (lowest index wins ties)
    reg [1:0] best;
    reg signed [33:0] second;
    integer o;
    always @(*) begin
        best = 2'd0;
        for (o = 1; o < NO; o = o + 1)
            if (logit[o] > logit[best]) best = o[1:0];
        second = 34'sh2_0000_0000;                       // most negative 34-bit value
        for (o = 0; o < NO; o = o + 1)
            if (o[1:0] != best && logit[o] > second) second = logit[o];
    end
    wire signed [34:0] mdiff = {logit[best][33], logit[best]} - {second[33], second};
    wire [31:0] margin_sat = (mdiff > 35'sd2147483647) ? 32'h7FFF_FFFF :
                             (mdiff < -35'sd2147483648) ? 32'h8000_0000 : mdiff[31:0];

    function [31:0] sat32;
        input signed [33:0] v;
        begin
            sat32 = (v > 34'sd2147483647) ? 32'h7FFF_FFFF : (v < -34'sd2147483648) ? 32'h8000_0000 : v[31:0];
        end
    endfunction

    integer k;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE; row <= 3'd0; col <= 3'd0; acc <= 34'sd0;
            for (k = 0; k < 8; k = k + 1) begin x[k] <= 8'sd0; h[k] <= 7'd0; end
            for (k = 0; k < 4; k = k + 1) logit[k] <= 34'sd0;
            done <= 1'b0; out_cls <= 2'd0; out_margin <= 32'd0; out_ts <= {TS_W{1'b0}};
            out_frame_id <= {WIN_IDX_W{1'b0}}; out_sat <= 8'd0; out_x <= 64'd0; out_h <= 64'd0;
            out_logit <= 128'd0;
        end else begin
            done <= 1'b0;
            case (state)
                S_IDLE: if (start & enable) begin
                    for (k = 0; k < 8; k = k + 1) begin
                        x[k] <= in_x[8*k +: 8];
                        h[k] <= 7'd0;
                    end
                    for (k = 0; k < 4; k = k + 1) logit[k] <= 34'sd0;
                    out_ts <= in_ts;
                    out_frame_id <= in_frame_id;
                    out_sat <= in_sat;
                    out_x <= in_x;
                    row <= 3'd0;
                    col <= 3'd0;
                    if (linear) begin
                        acc <= {{2{b2_0[31]}}, b2_0};
                        state <= S_L2;
                    end else begin
                        acc <= {{2{b1_0[31]}}, b1_0};
                        state <= S_L1;
                    end
                end
                S_L1: begin
                    if (col == 3'd7) begin
                        h[row] <= relu;
                        col <= 3'd0;
                        if (row == NH_M1) begin
                            row <= 3'd0;
                            acc <= {{2{b2_0[31]}}, b2_0};
                            state <= S_L2;
                        end else begin
                            row <= row_p1;
                            acc <= {{2{b1_next[31]}}, b1_next};
                        end
                    end else begin
                        acc <= sum;
                        col <= col + 3'd1;
                    end
                end
                S_L2: begin
                    if (col == n2_last) begin
                        logit[row[1:0]] <= sum;
                        col <= 3'd0;
                        if (row == NO_M1) begin
                            row <= 3'd0;
                            state <= S_FIN;
                        end else begin
                            row <= row_p1;
                            acc <= {{2{b2_next[31]}}, b2_next};
                        end
                    end else begin
                        acc <= sum;
                        col <= col + 3'd1;
                    end
                end
                S_FIN: begin
                    done <= 1'b1;
                    out_cls <= best;
                    out_margin <= margin_sat;
                    for (k = 0; k < 8; k = k + 1)
                        out_h[8*k +: 8] <= {1'b0, h[k]};
                    for (k = 0; k < 4; k = k + 1)
                        out_logit[32*k +: 32] <= (k < NO) ? sat32(logit[k]) : 32'd0;
                    state <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
            if (!enable) begin
                state <= S_IDLE;
                done <= 1'b0;
            end
        end
    end
endmodule

module hbci_ai_decoder #(
    parameter integer NH        = 4,
    parameter integer NO        = 2,
    parameter integer TS_W      = 32,
    parameter integer WIN_IDX_W = 16,
    parameter integer PRED_LOG2 = 2     // prediction FIFO depth = 2^PRED_LOG2
) (
    input  wire                 clk,
    input  wire                 rst_n,
    // control
    input  wire                 cfg_ai_en,
    input  wire                 feat_sync,
    input  wire [7:0]           cfg_ch_mask,
    input  wire [TS_W-1:0]      cfg_frame_span,
    // features from hbci_readout_core
    input  wire                 feat_valid,
    input  wire [2:0]           feat_ch,
    input  wire [31:0]          feat_energy,
    input  wire [TS_W-1:0]      feat_ts,
    input  wire                 feat_sat,
    input  wire [WIN_IDX_W-1:0] feat_win,
    // model bus
    input  wire                 model_we,
    input  wire [5:0]           model_addr,
    input  wire [31:0]          model_wdata,
    output wire [31:0]          model_rdata,
    input  wire                 crc_we,
    input  wire [31:0]          crc_wdata,
    output wire [31:0]          crc_expected,
    input  wire                 model_verify,
    input  wire                 model_clear_rej,
    output wire                 model_valid,
    output wire                 model_error,
    output wire                 model_busy,
    output wire                 model_rejected,
    output wire [15:0]          model_id,
    output wire [31:0]          stat_model_wr_rej,
    // predictions (FIFO head)
    output wire                 pred_valid,
    input  wire                 pred_ready,       // pop
    output wire [1:0]           pred_class,
    output wire [31:0]          pred_margin,
    output wire [TS_W-1:0]      pred_ts,
    output wire [WIN_IDX_W-1:0] pred_frame_id,
    output wire [15:0]          pred_seq,
    output wire [3:0]           pred_flags,       // bit0 sat, bit1 gap
    output wire [PRED_LOG2:0]   pred_count,
    output reg                  pred_strobe,      // one cycle per emitted prediction
    output reg  [1:0]           pred_class_direct,
    // counters
    output wire [31:0]          stat_frames,
    output reg  [31:0]          stat_pred,
    output wire [31:0]          stat_incomplete,
    output wire [31:0]          stat_dup,
    output wire [31:0]          stat_late,
    output wire [31:0]          stat_span,
    output reg  [31:0]          stat_busy,
    output reg  [31:0]          stat_pred_drop,
    output reg  [31:0]          stat_nomodel,
    output reg  [31:0]          stat_sat_frames,
    // last inferred frame
    output wire [WIN_IDX_W-1:0] last_frame_id,
    output wire [7:0]           last_missing,
    output wire [7:0]           last_sat,
    output wire [63:0]          last_x,
    output wire [63:0]          last_h,
    output wire [127:0]         last_logit,
    output wire [TS_W-1:0]      last_ts
`ifdef FORMAL
    , output wire                f_pend_v,         // formal probes (SymbiYosys only)
    output wire                  f_eng_busy,
    output wire                  f_frame_valid,
    output wire [63:0]           f_frame_x,
    output wire                  f_col_open,
    output wire [7:0]            f_col_seen,
    output wire [WIN_IDX_W-1:0]  f_col_id
`endif
);
    // ------------------------------------------------------------- model
    wire [NH*64-1:0] w1_flat;
    wire [NO*64-1:0] w2_flat;
    wire [NH*32-1:0] b1_flat;
    wire [NO*32-1:0] b2_flat;
    wire [95:0]      centre_flat;
    wire [23:0]      qshift_flat;
    wire [4:0]       s1;
    wire             linear;

    hbci_model_store #(.NH(NH), .NO(NO)) u_model (
        .clk(clk), .rst_n(rst_n), .ai_en(cfg_ai_en),
        .we(model_we), .addr(model_addr), .wdata(model_wdata), .rdata(model_rdata),
        .crc_we(crc_we), .crc_wdata(crc_wdata), .crc_expected(crc_expected),
        .verify(model_verify), .clear_rej(model_clear_rej),
        .valid(model_valid), .error(model_error), .busy(model_busy), .rejected(model_rejected),
        .stat_wr_rej(stat_model_wr_rej),
        .w1_flat(w1_flat), .w2_flat(w2_flat), .b1_flat(b1_flat), .b2_flat(b2_flat),
        .centre_flat(centre_flat), .qshift_flat(qshift_flat), .s1(s1), .linear(linear),
        .model_id(model_id)
    );

    // --------------------------------------------------------- quantiser
    wire [10:0]       q_l;
    wire signed [7:0] q_x;
    /* verilator lint_off UNUSEDSIGNAL */
    wire [10:0] q_l_unused = q_l;
    /* verilator lint_on UNUSEDSIGNAL */
    hbci_feat_quant u_quant (
        .energy(feat_energy), .centre(centre_flat[12*feat_ch +: 12]), .qshift(qshift_flat[3*feat_ch +: 3]),
        .enabled(cfg_ch_mask[feat_ch]), .l(q_l), .x(q_x)
    );

    // --------------------------------------------------------- collector
    wire                 frame_valid;
    wire [WIN_IDX_W-1:0] frame_id;
    wire [TS_W-1:0]      frame_ts;
    wire [63:0]          frame_x;
    wire [7:0]           frame_sat;

    hbci_frame_collector #(.TS_W(TS_W), .WIN_IDX_W(WIN_IDX_W)) u_collect (
`ifdef FORMAL
        .f_open(f_col_open), .f_seen(f_col_seen), .f_id(f_col_id),
`endif
        .clk(clk), .rst_n(rst_n), .enable(cfg_ai_en), .sync(feat_sync),
        .ch_mask(cfg_ch_mask), .frame_span(cfg_frame_span),
        .feat_valid(feat_valid), .feat_ch(feat_ch), .feat_x(q_x), .feat_ts(feat_ts),
        .feat_sat(feat_sat), .feat_win(feat_win),
        .frame_valid(frame_valid), .frame_id(frame_id), .frame_ts(frame_ts), .frame_x(frame_x),
        .frame_sat(frame_sat),
        .stat_frames(stat_frames), .stat_incomplete(stat_incomplete), .stat_dup(stat_dup),
        .stat_late(stat_late), .stat_span(stat_span), .last_missing(last_missing)
    );

    // ------------------------------------------------- pending register
    reg                  pend_v;
    reg [WIN_IDX_W-1:0]  pend_id;
    reg [TS_W-1:0]       pend_ts;
    reg [63:0]           pend_x;
    reg [7:0]            pend_sat;
    wire                 eng_busy;
    wire                 eng_start = pend_v & ~eng_busy & cfg_ai_en;
`ifdef FORMAL
    assign f_pend_v = pend_v;
    assign f_eng_busy = eng_busy;
    assign f_frame_valid = frame_valid;
    assign f_frame_x = frame_x;
`endif

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pend_v <= 1'b0; pend_id <= {WIN_IDX_W{1'b0}}; pend_ts <= {TS_W{1'b0}};
            pend_x <= 64'd0; pend_sat <= 8'd0;
            stat_busy <= 32'd0; stat_nomodel <= 32'd0;
        end else begin
            if (eng_start) pend_v <= 1'b0;
            if (frame_valid) begin
                if (!model_valid) begin
                    stat_nomodel <= stat_nomodel + 32'd1;
                end else if (pend_v & ~eng_start) begin
                    stat_busy <= stat_busy + 32'd1;
                end else begin
                    pend_v <= 1'b1; pend_id <= frame_id; pend_ts <= frame_ts;
                    pend_x <= frame_x; pend_sat <= frame_sat;
                end
            end
            if (!cfg_ai_en) pend_v <= 1'b0;
        end
    end

    // ------------------------------------------------------------ engine
    wire                 eng_done;
    wire [1:0]           eng_cls;
    wire [31:0]          eng_margin;
    wire [TS_W-1:0]      eng_ts;
    wire [WIN_IDX_W-1:0] eng_frame_id;
    wire [7:0]           eng_sat;

    hbci_mlp_engine #(.NH(NH), .NO(NO), .TS_W(TS_W), .WIN_IDX_W(WIN_IDX_W)) u_engine (
        .clk(clk), .rst_n(rst_n), .enable(cfg_ai_en), .start(eng_start), .busy(eng_busy),
        .in_x(pend_x), .in_frame_id(pend_id), .in_ts(pend_ts), .in_sat(pend_sat),
        .linear(linear), .s1(s1), .w1_flat(w1_flat), .w2_flat(w2_flat), .b1_flat(b1_flat), .b2_flat(b2_flat),
        .done(eng_done), .out_cls(eng_cls), .out_margin(eng_margin), .out_ts(eng_ts),
        .out_frame_id(eng_frame_id), .out_sat(eng_sat), .out_x(last_x), .out_h(last_h), .out_logit(last_logit)
    );
    assign last_frame_id = eng_frame_id;
    assign last_ts       = eng_ts;
    assign last_sat      = eng_sat;

    // --------------------------------------------------- prediction FIFO
    localparam integer DEPTH = 1 << PRED_LOG2;
    localparam integer PW = 2 + 32 + TS_W + WIN_IDX_W + 16 + 4;
    reg [PW-1:0]        pmem [0:DEPTH-1];
    reg [PRED_LOG2-1:0] pwr, prd;
    reg [PRED_LOG2:0]   pcnt;
    reg [15:0]          seq;
    reg                 gap;
    wire pfull = pcnt[PRED_LOG2];
    wire ppush = eng_done & ~pfull;
    wire ppop  = pred_valid & pred_ready;
    wire [3:0] pflags = {2'b00, gap, |eng_sat};
    wire [PW-1:0] pentry = {eng_cls, eng_margin, eng_ts, eng_frame_id, seq, pflags};
    wire [PW-1:0] phead = pmem[prd];

    assign pred_valid    = (pcnt != {(PRED_LOG2+1){1'b0}});
    assign pred_count    = pcnt;
    assign pred_flags    = phead[3:0];
    assign pred_seq      = phead[4 +: 16];
    assign pred_frame_id = phead[20 +: WIN_IDX_W];
    assign pred_ts       = phead[20+WIN_IDX_W +: TS_W];
    assign pred_margin   = phead[20+WIN_IDX_W+TS_W +: 32];
    assign pred_class    = phead[PW-1:PW-2];

    integer p;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (p = 0; p < DEPTH; p = p + 1) pmem[p] <= {PW{1'b0}};
            pwr <= {PRED_LOG2{1'b0}}; prd <= {PRED_LOG2{1'b0}}; pcnt <= {(PRED_LOG2+1){1'b0}};
            seq <= 16'd0; gap <= 1'b0; stat_pred <= 32'd0; stat_pred_drop <= 32'd0;
            stat_sat_frames <= 32'd0; pred_strobe <= 1'b0; pred_class_direct <= 2'd0;
        end else begin
            pred_strobe <= 1'b0;
            if (eng_done) begin
                if (|eng_sat) stat_sat_frames <= stat_sat_frames + 32'd1;
                if (pfull) begin
                    stat_pred_drop <= stat_pred_drop + 32'd1;
                    gap <= 1'b1;
                end else begin
                    pmem[pwr] <= pentry;
                    pwr <= pwr + {{(PRED_LOG2-1){1'b0}}, 1'b1};
                    seq <= seq + 16'd1;
                    gap <= 1'b0;
                    stat_pred <= stat_pred + 32'd1;
                    pred_strobe <= 1'b1;
                    pred_class_direct <= eng_cls;
                end
            end
            if (ppop) prd <= prd + {{(PRED_LOG2-1){1'b0}}, 1'b1};
            pcnt <= pcnt + (ppush ? {{PRED_LOG2{1'b0}}, 1'b1} : {(PRED_LOG2+1){1'b0}})
                         - (ppop  ? {{PRED_LOG2{1'b0}}, 1'b1} : {(PRED_LOG2+1){1'b0}});
        end
    end
endmodule

module hbci02_digital_top #(
    parameter integer NUM_CH    = 8,
    parameter integer CH_W      = 3,
    parameter integer SAMPLE_W  = 16,
    parameter integer TS_W      = 32,
    parameter integer SEQ_W     = 16,
    parameter integer FIFO_LOG2 = 4,
    parameter integer WIN_W     = 10,
    parameter integer ACC_W     = 48,
    parameter integer WIN_IDX_W = 16,
    parameter integer NH        = 4,
    parameter integer NO        = 2,
    parameter integer PRED_LOG2 = 2
) (
    input  wire                       clk,
    input  wire                       rst_n,
    // register bus: one write per cycle (reg_wr), combinational read data
    input  wire                       reg_wr,
    input  wire [7:0]                 reg_addr,
    input  wire [31:0]                reg_wdata,
    output reg  [31:0]                reg_rdata,
    // sample input (ADC style, no back-pressure)
    input  wire                       in_valid,
    input  wire [CH_W-1:0]            in_channel,
    input  wire signed [SAMPLE_W-1:0] in_sample,
    // record output (valid/ready)
    output wire                       rec_valid,
    input  wire                       rec_ready,
    output wire [1:0]                 rec_type,
    output wire [CH_W-1:0]            rec_channel,
    output wire [3:0]                 rec_flags,
    output wire [SEQ_W-1:0]           rec_seq,
    output wire [TS_W-1:0]            rec_ts,
    output wire [31:0]                rec_data,
    // direct prediction pins (when CTRL.pred_direct_en)
    output wire                       pred_strobe,
    output wire [1:0]                 pred_class_out,
    output wire                       pred_irq          // prediction FIFO not empty
);
    localparam [31:0] ID = 32'h4842_0204;              // "HB", 0x02, v0.4

    // ----------------------------------------------------------- registers
    reg        cfg_session_en, cfg_ai_en, cfg_bist_en, cfg_pred_direct;
    reg [1:0]  cfg_mode;
    reg [SAMPLE_W-1:0] cfg_threshold, cfg_hysteresis;
    reg [7:0]  cfg_refractory;
    reg [3:0]  cfg_alpha_shift;
    reg signed [15:0] cfg_b0, cfg_b1, cfg_b2, cfg_a1, cfg_a2;
    reg [3:0]  cfg_win_log2;
    reg [5:0]  cfg_energy_shift;
    reg [7:0]  cfg_ch_mask;
    reg [TS_W-1:0] cfg_frame_span;
    reg        feat_sync;                               // one-cycle pulse
    reg        pred_ack;                                // one-cycle pulse
    reg        model_verify, model_clear_rej;           // one-cycle pulses
    reg        bist_start, bist_clear;                  // one-cycle pulses
    reg [31:0] bist_len;

    wire wr = reg_wr & ~cfg_bist_en | reg_wr & (reg_addr == 8'h01 | reg_addr == 8'h3E | reg_addr == 8'h3F);
    wire w_ctrl = wr & (reg_addr == 8'h01);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cfg_session_en <= 1'b0; cfg_ai_en <= 1'b0; cfg_bist_en <= 1'b0; cfg_pred_direct <= 1'b0;
            cfg_mode <= 2'd0; cfg_threshold <= {SAMPLE_W{1'b0}}; cfg_hysteresis <= {SAMPLE_W{1'b0}};
            cfg_refractory <= 8'd0; cfg_alpha_shift <= 4'd0;
            cfg_b0 <= 16'sd0; cfg_b1 <= 16'sd0; cfg_b2 <= 16'sd0; cfg_a1 <= 16'sd0; cfg_a2 <= 16'sd0;
            cfg_win_log2 <= 4'd0; cfg_energy_shift <= 6'd0; cfg_ch_mask <= 8'hFF;
            cfg_frame_span <= {TS_W{1'b1}};
            feat_sync <= 1'b0; pred_ack <= 1'b0; model_verify <= 1'b0; model_clear_rej <= 1'b0;
            bist_start <= 1'b0; bist_clear <= 1'b0; bist_len <= 32'd0;
        end else begin
            feat_sync <= w_ctrl & reg_wdata[4];
            pred_ack <= wr & (reg_addr == 8'h34) & reg_wdata[0];
            model_verify <= wr & (reg_addr == 8'h39) & reg_wdata[0];
            model_clear_rej <= wr & (reg_addr == 8'h3A);
            bist_start <= wr & (reg_addr == 8'h3E) & reg_wdata[0];
            bist_clear <= wr & (reg_addr == 8'h3E) & reg_wdata[1];
            if (wr) begin
                case (reg_addr)
                    8'h01: begin
                        cfg_session_en <= reg_wdata[0];
                        cfg_mode <= reg_wdata[2:1];
                        cfg_ai_en <= reg_wdata[3];
                        cfg_bist_en <= reg_wdata[5];
                        cfg_pred_direct <= reg_wdata[6];
                    end
                    8'h02: cfg_threshold <= reg_wdata[SAMPLE_W-1:0];
                    8'h03: cfg_hysteresis <= reg_wdata[SAMPLE_W-1:0];
                    8'h04: cfg_refractory <= reg_wdata[7:0];
                    8'h05: cfg_alpha_shift <= reg_wdata[3:0];
                    8'h06: cfg_b0 <= reg_wdata[15:0];
                    8'h07: cfg_b1 <= reg_wdata[15:0];
                    8'h08: cfg_b2 <= reg_wdata[15:0];
                    8'h09: cfg_a1 <= reg_wdata[15:0];
                    8'h0A: cfg_a2 <= reg_wdata[15:0];
                    8'h0B: cfg_win_log2 <= reg_wdata[3:0];
                    8'h0C: cfg_energy_shift <= reg_wdata[5:0];
                    8'h0D: cfg_ch_mask <= reg_wdata[7:0];
                    8'h0E: cfg_frame_span <= reg_wdata[TS_W-1:0];
                    8'h3F: bist_len <= reg_wdata;
                    default: begin end
                endcase
            end
        end
    end

    // --------------------------------------------------------------- BIST
    // While CTRL.bist_en = 1 the LFSR replaces the external samples, the record
    // output is consumed internally and folded into the signature, and so is every
    // prediction. The external record output stays silent.
    wire                       bist_valid;
    wire [CH_W-1:0]            bist_ch;
    wire signed [SAMPLE_W-1:0] bist_sample;
    wire                       core_in_valid = cfg_bist_en ? bist_valid : in_valid;
    wire [CH_W-1:0]            core_in_ch    = cfg_bist_en ? bist_ch : in_channel;
    wire signed [SAMPLE_W-1:0] core_in_smp   = cfg_bist_en ? bist_sample : in_sample;
    wire                       core_rec_valid;
    wire                       core_rec_ready = cfg_bist_en ? 1'b1 : rec_ready;
    assign rec_valid = core_rec_valid & ~cfg_bist_en;

    // --------------------------------------------------------- readout core
    wire [TS_W-1:0] stat_samples, stat_rejected;
    wire [31:0] stat_drop_raw, stat_drop_event, stat_drop_feature, stat_event_missed, stat_fifo_hwm;
    wire                 feat_valid, feat_sat;
    wire [CH_W-1:0]      feat_ch;
    wire [31:0]          feat_energy;
    wire [TS_W-1:0]      feat_ts;
    wire [WIN_IDX_W-1:0] feat_win;

    hbci_readout_core #(
        .NUM_CH(NUM_CH), .CH_W(CH_W), .SAMPLE_W(SAMPLE_W), .TS_W(TS_W), .SEQ_W(SEQ_W),
        .FIFO_LOG2(FIFO_LOG2), .WIN_W(WIN_W), .ACC_W(ACC_W), .WIN_IDX_W(WIN_IDX_W)
    ) u_readout (
        .clk(clk), .rst_n(rst_n),
        .cfg_session_en(cfg_session_en), .cfg_mode(cfg_mode),
        .cfg_threshold(cfg_threshold), .cfg_hysteresis(cfg_hysteresis),
        .cfg_refractory(cfg_refractory), .cfg_alpha_shift(cfg_alpha_shift),
        .cfg_b0(cfg_b0), .cfg_b1(cfg_b1), .cfg_b2(cfg_b2), .cfg_a1(cfg_a1), .cfg_a2(cfg_a2),
        .cfg_win_log2(cfg_win_log2), .cfg_energy_shift(cfg_energy_shift), .feat_sync(feat_sync),
        .in_valid(core_in_valid), .in_channel(core_in_ch), .in_sample(core_in_smp),
        .rec_valid(core_rec_valid), .rec_ready(core_rec_ready),
        .rec_type(rec_type), .rec_channel(rec_channel), .rec_flags(rec_flags),
        .rec_seq(rec_seq), .rec_ts(rec_ts), .rec_data(rec_data),
        .stat_samples(stat_samples), .stat_rejected(stat_rejected),
        .stat_drop_raw(stat_drop_raw), .stat_drop_event(stat_drop_event),
        .stat_drop_feature(stat_drop_feature), .stat_event_missed(stat_event_missed),
        .stat_fifo_hwm(stat_fifo_hwm),
        .ai_feat_valid(feat_valid), .ai_feat_ch(feat_ch), .ai_feat_energy(feat_energy),
        .ai_feat_ts(feat_ts), .ai_feat_saturated(feat_sat), .ai_feat_win(feat_win)
    );

    // ------------------------------------------------------------ decoder
    wire        model_region = (reg_addr >= 8'h40) & (reg_addr < 8'h6E);
    wire        model_we = wr & model_region;
    wire [5:0]  model_addr = reg_addr[5:0] - 6'd0;      // 0x40 -> 0 (low six bits of 0x40..0x6D are 0..45)
    wire [31:0] model_rdata, crc_expected;
    wire        model_valid, model_error, model_busy, model_rejected;
    wire [15:0] model_id;
    wire [31:0] stat_model_wr_rej;
    wire        pred_valid;
    wire [1:0]  pred_class;
    wire [31:0] pred_margin;
    wire [TS_W-1:0] pred_ts;
    wire [WIN_IDX_W-1:0] pred_frame_id;
    wire [15:0] pred_seq;
    wire [3:0]  pred_flags;
    wire [PRED_LOG2:0] pred_count;
    wire        pred_strobe_i;
    wire [1:0]  pred_class_direct;
    wire [31:0] ai_frames, ai_pred, ai_incomplete, ai_dup, ai_late, ai_span, ai_busy, ai_pred_drop,
                ai_nomodel, ai_sat_frames;
    wire [WIN_IDX_W-1:0] last_frame_id;
    wire [7:0]  last_missing, last_sat;
    wire [63:0] last_x, last_h;
    wire [127:0] last_logit;
    wire [TS_W-1:0] last_ts;
    wire        bist_pred_pop;
    wire        pred_pop = cfg_bist_en ? bist_pred_pop : pred_ack;

    hbci_ai_decoder #(
        .NH(NH), .NO(NO), .TS_W(TS_W), .WIN_IDX_W(WIN_IDX_W), .PRED_LOG2(PRED_LOG2)
    ) u_ai (
        .clk(clk), .rst_n(rst_n),
        .cfg_ai_en(cfg_session_en & cfg_ai_en), .feat_sync(feat_sync),
        .cfg_ch_mask(cfg_ch_mask), .cfg_frame_span(cfg_frame_span),
        .feat_valid(feat_valid), .feat_ch(feat_ch), .feat_energy(feat_energy), .feat_ts(feat_ts),
        .feat_sat(feat_sat), .feat_win(feat_win),
        .model_we(model_we), .model_addr(model_addr), .model_wdata(reg_wdata), .model_rdata(model_rdata),
        .crc_we(wr & (reg_addr == 8'h38)), .crc_wdata(reg_wdata), .crc_expected(crc_expected),
        .model_verify(model_verify), .model_clear_rej(model_clear_rej),
        .model_valid(model_valid), .model_error(model_error), .model_busy(model_busy),
        .model_rejected(model_rejected), .model_id(model_id), .stat_model_wr_rej(stat_model_wr_rej),
        .pred_valid(pred_valid), .pred_ready(pred_pop), .pred_class(pred_class), .pred_margin(pred_margin),
        .pred_ts(pred_ts), .pred_frame_id(pred_frame_id), .pred_seq(pred_seq), .pred_flags(pred_flags),
        .pred_count(pred_count), .pred_strobe(pred_strobe_i), .pred_class_direct(pred_class_direct),
        .stat_frames(ai_frames), .stat_pred(ai_pred), .stat_incomplete(ai_incomplete), .stat_dup(ai_dup),
        .stat_late(ai_late), .stat_span(ai_span), .stat_busy(ai_busy), .stat_pred_drop(ai_pred_drop),
        .stat_nomodel(ai_nomodel), .stat_sat_frames(ai_sat_frames),
        .last_frame_id(last_frame_id), .last_missing(last_missing), .last_sat(last_sat),
        .last_x(last_x), .last_h(last_h), .last_logit(last_logit), .last_ts(last_ts)
    );
    assign pred_strobe    = pred_strobe_i & cfg_pred_direct;
    assign pred_class_out = cfg_pred_direct ? pred_class_direct : 2'd0;
    assign pred_irq       = pred_valid & ~cfg_bist_en;

    // ------------------------------------------------------------- BIST block
    wire [31:0] bist_sig, bist_count;
    wire        bist_running;
    hbci_bist #(.CH_W(CH_W), .SAMPLE_W(SAMPLE_W), .TS_W(TS_W), .SEQ_W(SEQ_W), .WIN_IDX_W(WIN_IDX_W)) u_bist (
        .clk(clk), .rst_n(rst_n), .enable(cfg_bist_en), .start(bist_start), .clear(bist_clear),
        .len(bist_len), .running(bist_running),
        .smp_valid(bist_valid), .smp_ch(bist_ch), .smp_sample(bist_sample),
        .rec_valid(core_rec_valid & cfg_bist_en), .rec_type(rec_type), .rec_channel(rec_channel),
        .rec_flags(rec_flags), .rec_seq(rec_seq), .rec_ts(rec_ts), .rec_data(rec_data),
        .pred_valid(pred_valid & cfg_bist_en), .pred_pop(bist_pred_pop), .pred_class(pred_class),
        .pred_margin(pred_margin), .pred_ts(pred_ts), .pred_frame_id(pred_frame_id), .pred_seq(pred_seq),
        .pred_flags(pred_flags),
        .signature(bist_sig), .count(bist_count)
    );

    // --------------------------------------------------------------- reads
    wire [31:0] x_ts_samples  = {{(32-TS_W){1'b0}}, stat_samples};
    wire [31:0] x_ts_rejected = {{(32-TS_W){1'b0}}, stat_rejected};
    wire [31:0] x_pred_ts     = {{(32-TS_W){1'b0}}, pred_ts};
    wire [31:0] x_last_ts     = {{(32-TS_W){1'b0}}, last_ts};
    wire [31:0] x_frame_span  = {{(32-TS_W){1'b0}}, cfg_frame_span};
    wire [15:0] x_pred_frame  = {{(16-WIN_IDX_W){1'b0}}, pred_frame_id};
    wire [15:0] x_last_frame  = {{(16-WIN_IDX_W){1'b0}}, last_frame_id};
    /* verilator lint_off UNUSEDSIGNAL */
    wire [31:0] x_pred_count  = {{(31-PRED_LOG2){1'b0}}, pred_count};   // PRED_STATUS carries 3 count bits
    /* verilator lint_on UNUSEDSIGNAL */

    always @(*) begin
        reg_rdata = 32'd0;
        if (model_region) reg_rdata = model_rdata;
        else case (reg_addr)
            8'h00: reg_rdata = ID;
            8'h01: reg_rdata = {25'd0, cfg_pred_direct, cfg_bist_en, 1'b0, cfg_ai_en, cfg_mode, cfg_session_en};
            8'h02: reg_rdata = {{(32-SAMPLE_W){1'b0}}, cfg_threshold};
            8'h03: reg_rdata = {{(32-SAMPLE_W){1'b0}}, cfg_hysteresis};
            8'h04: reg_rdata = {24'd0, cfg_refractory};
            8'h05: reg_rdata = {28'd0, cfg_alpha_shift};
            8'h06: reg_rdata = {{16{cfg_b0[15]}}, cfg_b0};
            8'h07: reg_rdata = {{16{cfg_b1[15]}}, cfg_b1};
            8'h08: reg_rdata = {{16{cfg_b2[15]}}, cfg_b2};
            8'h09: reg_rdata = {{16{cfg_a1[15]}}, cfg_a1};
            8'h0A: reg_rdata = {{16{cfg_a2[15]}}, cfg_a2};
            8'h0B: reg_rdata = {28'd0, cfg_win_log2};
            8'h0C: reg_rdata = {26'd0, cfg_energy_shift};
            8'h0D: reg_rdata = {24'd0, cfg_ch_mask};
            8'h0E: reg_rdata = x_frame_span;
            8'h10: reg_rdata = x_ts_samples;
            8'h11: reg_rdata = x_ts_rejected;
            8'h12: reg_rdata = stat_drop_raw;
            8'h13: reg_rdata = stat_drop_event;
            8'h14: reg_rdata = stat_drop_feature;
            8'h15: reg_rdata = stat_event_missed;
            8'h16: reg_rdata = stat_fifo_hwm;
            8'h18: reg_rdata = ai_frames;
            8'h19: reg_rdata = ai_pred;
            8'h1A: reg_rdata = ai_incomplete;
            8'h1B: reg_rdata = ai_dup;
            8'h1C: reg_rdata = ai_late;
            8'h1D: reg_rdata = ai_span;
            8'h1E: reg_rdata = ai_busy;
            8'h1F: reg_rdata = ai_pred_drop;
            8'h20: reg_rdata = ai_nomodel;
            8'h21: reg_rdata = ai_sat_frames;
            8'h22: reg_rdata = stat_model_wr_rej;
            8'h24: reg_rdata = {last_sat, last_missing, x_last_frame};
            8'h25: reg_rdata = last_x[31:0];
            8'h26: reg_rdata = last_x[63:32];
            8'h27: reg_rdata = last_h[31:0];
            8'h28: reg_rdata = last_h[63:32];
            8'h29: reg_rdata = last_logit[31:0];
            8'h2A: reg_rdata = last_logit[63:32];
            8'h2B: reg_rdata = last_logit[95:64];
            8'h2C: reg_rdata = last_logit[127:96];
            8'h2D: reg_rdata = x_last_ts;
            8'h30: reg_rdata = pred_valid ? {22'd0, pred_class, pred_flags, x_pred_count[2:0], 1'b1} : 32'd0;
            8'h31: reg_rdata = pred_valid ? pred_margin : 32'd0;
            8'h32: reg_rdata = pred_valid ? x_pred_ts : 32'd0;
            8'h33: reg_rdata = pred_valid ? {x_pred_frame, pred_seq} : 32'd0;
            8'h38: reg_rdata = crc_expected;
            8'h3A: reg_rdata = {model_id, 12'd0, model_rejected, model_busy, model_error, model_valid};
            8'h3C: reg_rdata = bist_sig;
            8'h3D: reg_rdata = bist_count;
            8'h3E: reg_rdata = {31'd0, bist_running};
            8'h3F: reg_rdata = bist_len;
            default: reg_rdata = 32'd0;
        endcase
    end
endmodule

module hbci_bist #(
    parameter integer CH_W      = 3,
    parameter integer SAMPLE_W  = 16,
    parameter integer TS_W      = 32,
    parameter integer SEQ_W     = 16,
    parameter integer WIN_IDX_W = 16
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       enable,
    input  wire                       start,
    input  wire                       clear,
    input  wire [31:0]                len,
    output reg                        running,
    output reg                        smp_valid,
    output reg  [CH_W-1:0]            smp_ch,
    output reg  signed [SAMPLE_W-1:0] smp_sample,
    input  wire                       rec_valid,
    input  wire [1:0]                 rec_type,
    input  wire [CH_W-1:0]            rec_channel,
    input  wire [3:0]                 rec_flags,
    input  wire [SEQ_W-1:0]           rec_seq,
    input  wire [TS_W-1:0]            rec_ts,
    input  wire [31:0]                rec_data,
    input  wire                       pred_valid,
    output wire                       pred_pop,
    input  wire [1:0]                 pred_class,
    input  wire [31:0]                pred_margin,
    input  wire [TS_W-1:0]            pred_ts,
    input  wire [WIN_IDX_W-1:0]       pred_frame_id,
    input  wire [15:0]                pred_seq,
    input  wire [3:0]                 pred_flags,
    output reg  [31:0]                signature,
    output reg  [31:0]                count
);
    reg [31:0]     lfsr;
    reg [31:0]     remaining;
    reg [1:0]      phase;
    reg [CH_W-1:0] ch_cnt;
    assign pred_pop = enable & pred_valid;

    function [31:0] xs32;
        input [31:0] s;
        reg [31:0] t;
        begin
            t = s ^ (s << 13);
            t = t ^ (t >> 17);
            xs32 = t ^ (t << 5);
        end
    endfunction

    function [31:0] fold;
        input [31:0] sig;
        input [31:0] w;
        begin
            fold = {sig[26:0], sig[31:27]} ^ w;
        end
    endfunction

    wire [31:0] rec_meta  = {{(26-CH_W-SEQ_W){1'b0}}, rec_type, rec_channel, rec_flags, rec_seq};
    wire [31:0] rec_ts32  = {{(32-TS_W){1'b0}}, rec_ts};
    wire [31:0] pred_ids  = {{(16-WIN_IDX_W){1'b0}}, pred_frame_id, pred_seq};
    wire [31:0] pred_meta = {26'd0, pred_class, pred_flags};
    wire [31:0] pred_ts32 = {{(32-TS_W){1'b0}}, pred_ts};
    wire [31:0] sig_rec   = fold(fold(fold(signature, rec_data), rec_ts32), rec_meta);
    wire [31:0] sig_pred  = fold(fold(fold(fold(sig_rec, pred_margin), pred_ts32), pred_ids), pred_meta);
    wire [31:0] sig_ponly = fold(fold(fold(fold(signature, pred_margin), pred_ts32), pred_ids), pred_meta);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            lfsr <= 32'h2545_F491; remaining <= 32'd0; phase <= 2'd0; running <= 1'b0; ch_cnt <= {CH_W{1'b0}};
            smp_valid <= 1'b0; smp_ch <= {CH_W{1'b0}}; smp_sample <= {SAMPLE_W{1'b0}};
            signature <= 32'd0; count <= 32'd0;
        end else begin
            smp_valid <= 1'b0;
            if (clear) begin
                signature <= 32'd0; count <= 32'd0; lfsr <= 32'h2545_F491; ch_cnt <= {CH_W{1'b0}};
                running <= 1'b0; remaining <= 32'd0; phase <= 2'd0;
            end else if (start & enable) begin
                running <= 1'b1; remaining <= len; phase <= 2'd0;
            end else if (running) begin
                phase <= phase + 2'd1;
                if (phase == 2'd3) begin
                    if (remaining == 32'd0) begin
                        running <= 1'b0;
                    end else begin
                        smp_valid <= 1'b1;
                        smp_ch <= ch_cnt;
                        smp_sample <= lfsr[SAMPLE_W-1:0];
                        lfsr <= xs32(lfsr);
                        ch_cnt <= ch_cnt + {{(CH_W-1){1'b0}}, 1'b1};
                        remaining <= remaining - 32'd1;
                    end
                end
            end
            if (enable & (rec_valid | pred_valid)) begin
                signature <= rec_valid ? (pred_valid ? sig_pred : sig_rec) : sig_ponly;
                count <= count + {31'd0, rec_valid} + {31'd0, pred_valid};
            end
        end
    end
endmodule

module hbci_spi_sync (
    input  wire clk,
    input  wire rst_n,
    input  wire sclk,
    input  wire cs_n,
    input  wire mosi,
    output wire active,        // CS low (synchronised)
    output wire start,         // CS fell this cycle
    output wire stop,          // CS rose this cycle
    output wire rise,          // SCLK rising edge this cycle (while CS low)
    output wire fall,          // SCLK falling edge this cycle (while CS low)
    output wire din            // MOSI, synchronised
);
    reg [2:0] sclk_q, cs_q;
    reg [1:0] mosi_q;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sclk_q <= 3'd0; cs_q <= 3'b111; mosi_q <= 2'd0;
        end else begin
            sclk_q <= {sclk_q[1:0], sclk};
            cs_q   <= {cs_q[1:0], cs_n};
            mosi_q <= {mosi_q[0], mosi};
        end
    end
    assign active = ~cs_q[1];
    assign start  = cs_q[2] & ~cs_q[1];
    assign stop   = ~cs_q[2] & cs_q[1];
    assign rise   = active & ~sclk_q[2] & sclk_q[1];
    assign fall   = active & sclk_q[2] & ~sclk_q[1];
    assign din    = mosi_q[1];
endmodule

module hbci_spi_regbus (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        sclk,
    input  wire        cs_n,
    input  wire        mosi,
    output reg         miso,
    output reg         reg_wr,
    output reg  [7:0]  reg_addr,
    output reg  [31:0] reg_wdata,
    input  wire [31:0] reg_rdata,
    output reg  [31:0] stat_spi_frames   // completed 40-bit transactions
);
    wire active, start, stop, rise, fall, din;
    hbci_spi_sync u_sync (.clk(clk), .rst_n(rst_n), .sclk(sclk), .cs_n(cs_n), .mosi(mosi),
                          .active(active), .start(start), .stop(stop), .rise(rise), .fall(fall), .din(din));
    reg [5:0]  nbit;
    reg [30:0] shift_in;           // the 32nd bit is combined with din when a word completes
    reg [31:0] shift_out;
    reg        is_wr;
    /* verilator lint_off UNUSEDSIGNAL */
    wire unused_stop = stop;
    /* verilator lint_on UNUSEDSIGNAL */

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            nbit <= 6'd0; shift_in <= 31'd0; shift_out <= 32'd0; is_wr <= 1'b0; miso <= 1'b0;
            reg_wr <= 1'b0; reg_addr <= 8'd0; reg_wdata <= 32'd0; stat_spi_frames <= 32'd0;
        end else begin
            reg_wr <= 1'b0;
            if (start) begin
                nbit <= 6'd0;
                miso <= 1'b0;
            end else if (rise) begin
                shift_in <= {shift_in[29:0], din};
                nbit <= nbit + 6'd1;
                if (nbit == 6'd7) begin                         // command byte complete
                    is_wr <= shift_in[6];
                    reg_addr <= {1'b0, shift_in[5:0], din};
                end
                if (nbit == 6'd39) begin
                    if (is_wr) begin
                        reg_wr <= 1'b1;
                        reg_wdata <= {shift_in, din};
                    end
                    stat_spi_frames <= stat_spi_frames + 32'd1;
                end
            end else if (fall) begin
                if (nbit == 6'd8) begin                         // first data bit of a read
                    shift_out <= {reg_rdata[30:0], 1'b0};
                    miso <= is_wr ? 1'b0 : reg_rdata[31];
                end else if (nbit > 6'd8 && nbit < 6'd40) begin
                    miso <= is_wr ? 1'b0 : shift_out[31];
                    shift_out <= {shift_out[30:0], 1'b0};
                end
            end
            if (!active) miso <= 1'b0;
        end
    end
endmodule

module hbci_spi_samples #(
    parameter integer CH_W     = 3,
    parameter integer SAMPLE_W = 16
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       sclk,
    input  wire                       cs_n,
    input  wire                       mosi,
    output reg                        in_valid,
    output reg  [CH_W-1:0]            in_channel,
    output reg  signed [SAMPLE_W-1:0] in_sample,
    output reg  [31:0]                stat_parity_err
);
    wire active, start, stop, rise, fall, din;
    hbci_spi_sync u_sync (.clk(clk), .rst_n(rst_n), .sclk(sclk), .cs_n(cs_n), .mosi(mosi),
                          .active(active), .start(start), .stop(stop), .rise(rise), .fall(fall), .din(din));
    reg [4:0]  nbit;
    reg [22:0] shift_in;
    /* verilator lint_off UNUSEDSIGNAL */
    wire unused_stop = stop;
    wire unused_fall = fall;
    wire unused_active = active;
    /* verilator lint_on UNUSEDSIGNAL */
    wire [23:0] frame = {shift_in, din};
    wire parity_ok = (^{frame[23:17], frame[15:0]}) == frame[16];   // even parity: bit 16 = XOR of the others

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            nbit <= 5'd0; shift_in <= 23'd0; in_valid <= 1'b0; in_channel <= {CH_W{1'b0}};
            in_sample <= {SAMPLE_W{1'b0}}; stat_parity_err <= 32'd0;
        end else begin
            in_valid <= 1'b0;
            if (start) begin
                nbit <= 5'd0;
            end else if (rise) begin
                shift_in <= frame[22:0];
                if (nbit == 5'd23) begin
                    nbit <= 5'd0;
                    if (parity_ok) begin
                        in_valid   <= 1'b1;
                        in_channel <= frame[21 +: CH_W];
                        in_sample  <= frame[SAMPLE_W-1:0];
                    end else begin
                        stat_parity_err <= stat_parity_err + 32'd1;
                    end
                end else begin
                    nbit <= nbit + 5'd1;
                end
            end
        end
    end
endmodule

module hbci_rec_serial #(
    parameter integer CH_W  = 3,
    parameter integer SEQ_W = 16,
    parameter integer TS_W  = 32
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              rec_valid,
    output wire              rec_ready,
    input  wire [1:0]        rec_type,
    input  wire [CH_W-1:0]   rec_channel,
    input  wire [3:0]        rec_flags,
    input  wire [SEQ_W-1:0]  rec_seq,
    input  wire [TS_W-1:0]   rec_ts,
    input  wire [31:0]       rec_data,
    output reg               sdo,
    output reg               sfrm
);
    reg [95:0] sh;
    reg [6:0]  nbit;
    reg        busy;
    assign rec_ready = ~busy;
    wire [95:0] word = {{(96-2-CH_W-4-SEQ_W-TS_W-32){1'b0}}, rec_type, rec_channel, rec_flags, rec_seq, rec_ts, rec_data};
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sh <= 96'd0; nbit <= 7'd0; busy <= 1'b0; sdo <= 1'b0; sfrm <= 1'b0;
        end else begin
            if (!busy) begin
                sdo <= 1'b0; sfrm <= 1'b0;
                if (rec_valid) begin
                    busy <= 1'b1; sh <= word; nbit <= 7'd0;
                end
            end else begin
                sdo <= sh[95]; sfrm <= 1'b1;
                sh <= {sh[94:0], 1'b0};
                nbit <= nbit + 7'd1;
                if (nbit == 7'd95) busy <= 1'b0;
            end
        end
    end
endmodule

module hbci02_chip_top #(
    parameter integer NUM_CH    = 8,
    parameter integer CH_W      = 3,
    parameter integer SAMPLE_W  = 16,
    parameter integer TS_W      = 32,
    parameter integer SEQ_W     = 16,
    parameter integer FIFO_LOG2 = 4,
    parameter integer WIN_W     = 10,
    parameter integer ACC_W     = 48,
    parameter integer WIN_IDX_W = 16,
    parameter integer NH        = 4,
    parameter integer NO        = 2,
    parameter integer PRED_LOG2 = 2
) (
    input  wire clk,
    input  wire rst_n,
    input  wire spi_sclk,
    input  wire spi_cs_n,
    input  wire spi_mosi,
    output wire spi_miso,
    input  wire smp_sclk,
    input  wire smp_cs_n,
    input  wire smp_mosi,
    output wire rec_sdo,
    output wire rec_sfrm,
    output wire pred_strobe,
    output wire [1:0] pred_class,
    output wire pred_irq
);
    wire        reg_wr;
    wire [7:0]  reg_addr;
    wire [31:0] reg_wdata, reg_rdata, core_rdata;
    wire [31:0] stat_spi_frames, stat_parity_err;
    wire        in_valid;
    wire [CH_W-1:0] in_channel;
    wire signed [SAMPLE_W-1:0] in_sample;
    wire        rec_valid, rec_ready;
    wire [1:0]  rec_type;
    wire [CH_W-1:0] rec_channel;
    wire [3:0]  rec_flags;
    wire [SEQ_W-1:0] rec_seq;
    wire [TS_W-1:0] rec_ts;
    wire [31:0] rec_data;

    hbci_spi_regbus u_spi (
        .clk(clk), .rst_n(rst_n), .sclk(spi_sclk), .cs_n(spi_cs_n), .mosi(spi_mosi), .miso(spi_miso),
        .reg_wr(reg_wr), .reg_addr(reg_addr), .reg_wdata(reg_wdata), .reg_rdata(reg_rdata),
        .stat_spi_frames(stat_spi_frames)
    );
    hbci_spi_samples #(.CH_W(CH_W), .SAMPLE_W(SAMPLE_W)) u_smp (
        .clk(clk), .rst_n(rst_n), .sclk(smp_sclk), .cs_n(smp_cs_n), .mosi(smp_mosi),
        .in_valid(in_valid), .in_channel(in_channel), .in_sample(in_sample), .stat_parity_err(stat_parity_err)
    );
    // Two chip-level status words at 0x70 / 0x71 (above the digital top's map).
    assign reg_rdata = (reg_addr == 8'h70) ? stat_spi_frames : (reg_addr == 8'h71) ? stat_parity_err : core_rdata;

    hbci02_digital_top #(
        .NUM_CH(NUM_CH), .CH_W(CH_W), .SAMPLE_W(SAMPLE_W), .TS_W(TS_W), .SEQ_W(SEQ_W), .FIFO_LOG2(FIFO_LOG2),
        .WIN_W(WIN_W), .ACC_W(ACC_W), .WIN_IDX_W(WIN_IDX_W), .NH(NH), .NO(NO), .PRED_LOG2(PRED_LOG2)
    ) u_core (
        .clk(clk), .rst_n(rst_n),
        .reg_wr(reg_wr), .reg_addr(reg_addr), .reg_wdata(reg_wdata), .reg_rdata(core_rdata),
        .in_valid(in_valid), .in_channel(in_channel), .in_sample(in_sample),
        .rec_valid(rec_valid), .rec_ready(rec_ready), .rec_type(rec_type), .rec_channel(rec_channel),
        .rec_flags(rec_flags), .rec_seq(rec_seq), .rec_ts(rec_ts), .rec_data(rec_data),
        .pred_strobe(pred_strobe), .pred_class_out(pred_class), .pred_irq(pred_irq)
    );
    hbci_rec_serial #(.CH_W(CH_W), .SEQ_W(SEQ_W), .TS_W(TS_W)) u_rec (
        .clk(clk), .rst_n(rst_n), .rec_valid(rec_valid), .rec_ready(rec_ready), .rec_type(rec_type),
        .rec_channel(rec_channel), .rec_flags(rec_flags), .rec_seq(rec_seq), .rec_ts(rec_ts), .rec_data(rec_data),
        .sdo(rec_sdo), .sfrm(rec_sfrm)
    );
endmodule
